// OpenCode resolves a local plugin directory's server entry as <dir>/server or <dir>/index;
// package.json "main" is not consulted.
export { default } from "./src/index.ts"

#!/usr/bin/env bun
// Hub server entry point (`hub-server`, aliases `opencode-hub` and `opencode-voice-hub`): `bun bin/hub.ts [--help | --version]`,
// configured by HUB_* env vars over ~/.config/hub/hub.json ($HUB_CONFIG); see src/central/config.ts. Serves the
// built web app (web/dist, `npm run build:web`) from disk. The standalone binaries embed it instead
// (scripts/build-binaries.sh).
import { readFileSync } from "node:fs"
import path from "node:path"
import { diskAssets } from "../src/central/assets"
import { runHub } from "../src/central/main"

const root = path.join(import.meta.dir, "..")
const version = (() => {
  try {
    return String(JSON.parse(readFileSync(path.join(root, "package.json"), "utf8")).version ?? "0.0.0")
  } catch {
    return "0.0.0"
  }
})()

runHub({ web: diskAssets(path.join(root, "web", "dist")), version })

// Hub server plugin: a thin "spoke" that connects this OpenCode process to the hub. The web
// console, phones and (optional) Voice speech live on the hub; this side only exposes sessions, forwards
// their events, and runs remote / voice turns and permission replies on request.
import { mkdirSync, readFileSync } from "node:fs"
import { homedir, hostname } from "node:os"
import { fileURLToPath } from "node:url"
// Types only: @opencode/plugin's runtime entry loads its whole schema graph (~1 s cold) for an identity define().
import type { Plugin } from "@opencode/plugin"
import { prepareConfigPath } from "./config"
import { HubRpc, VoiceRpc } from "./rpc"
import { jobFromInfo, type JobInfo } from "./protocol"
import { checkServer, parseServerInput } from "./setup"
import { defineConciergeAgent } from "./spoke/concierge-agent"
import { CONCIERGE_FRONT_RULES, CONCIERGE_FRONT_TOOLS, defineVoiceFrontAgent, leanFrontSystem, FRONT_RELAY_DESCRIPTION, FRONT_RELAY_TOOL, FRONT_SEND_DESCRIPTION, FRONT_SEND_TOOL, FRONT_STOP_DESCRIPTION, FRONT_STOP_TOOL, VOICE_FRONT_AGENT } from "./spoke/voice-front"

import { CONCIERGE_AGENT, CONCIERGE_TOOLS } from "../packages/protocol/src/concierge.ts"
import { defaultHubBinDir, envInjector, hubBinDir, ShellCorrelator, stripInheritedHubEnv } from "./spoke/env-inject"
import { herdrRunner } from "./spoke/herdr"
import { launchSource } from "./spoke/launch-source"
import { HubRpcError, hubMsg, hubWho } from "./spoke/hub-rpc"
import { HUB_TOOL, HUB_TOOL_DESCRIPTION, HUB_TOOL_INPUT, runHubTool } from "./spoke/hub-tool"
import { SendOutbox } from "./spoke/send-outbox"
import { cliEntry, installLaunchers, linkUserBin, standaloneHubctl } from "./spoke/launchers"
import { listServiceSessions } from "./spoke/listing"
import { conciergeLockFiles, ensureLocalHub } from "./spoke/localhub"
import { hintStateDirOnce, resolveHubStateDir } from "./migrate"
import path from "node:path"
import { nodeConfigPath, readWorkspaceRoots } from "./spoke/node-roots"
import { PromptReferences } from "./spoke/prompt-refs"
import { PROFILE_TOOL, PROFILE_TOOL_DESCRIPTION, PROFILE_TOOL_INPUT } from "./spoke/profile-apply"
import { listedNames, namesReader, replyPermission, serverNames, vcsReader, type PermissionLocation, type VcsReader } from "./spoke/locations"
import { fetchOwnMedia, foregroundEndpoint, formOutcome } from "./spoke/own-server"
import { joinProcess, type Membership } from "./spoke/singleton"
import { applySessionContext, sortTools } from "./spoke/session-context"
import { detectKind, Spoke, SpokeError, type FormAction, type SpokeHost } from "./spoke/spoke"
import { registerAcutisLabsProvider } from "./opencode/acutis-labs-provider"

/** Where the spoke keeps the IDs of Concierge sessions (always restricted to the Concierge's tools). */
/** Written in the state dir; also read from the other default places, so a lock from before an upgrade still holds. */
const conciergeLocks = () => {
  const { file, read } = conciergeLockFiles()
  return { conciergeLockFile: file, conciergeLockReadFiles: read }
}

type Context = Parameters<Parameters<typeof Plugin.define>[0]["setup"]>[0]

/** Plugin.define without importing it (it returns its argument). */
const definePlugin = (plugin: Plugin.Plugin): Plugin.Plugin => plugin

/** One registration with OpenCode; a failure is logged and never stops the others. */
async function attempt(what: string, register: () => Promise<unknown> | undefined): Promise<void> {
  try {
    await register()
  } catch (cause) {
    console.error(`[hub] could not ${what}`, cause)
  }
}

const VOICE_STYLE =
  "This message came from a voice conversation and your reply will be read aloud. " +
  "Answer in at most three short sentences of plain speech: no markdown, code blocks, tables, or lists. " +
  "Keep using tools as needed; only the final reply must be short."

function pluginVersion(): string {
  try {
    return String(JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8")).version ?? "0.0.0")
  } catch {
    return "0.0.0"
  }
}

/**
 * The most recent root sessions with their workspace (the spoke's session listing): the history window plus
 * `include`. The background service lists every session of its server; a foreground `opencode serve` lists, from
 * its own server, only the sessions of the locations it loaded (`scope`), so idle sessions of a loaded project are
 * online without having run in this process, and nothing of other projects is claimed.
 */
async function listRecent(kind: "service" | "standalone", scope: () => string[], options?: { days: number; max: number; include: readonly string[]; signal?: AbortSignal }) {
  if (kind === "service") {
    const { Service } = await import("@opencode/client/service")
    const { OpenCode } = await import("@opencode/client")
    const endpoint = await Service.discover()
    if (!endpoint) return []
    const client = OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) ?? {} })
    return listServiceSessions(client, options ?? {})
  }
  const client = await ownClient(kind)
  if (!client) return []
  return listServiceSessions(client, { ...(options ?? {}), scope: scope() })
}

/** This process can list sessions: the background service, or a foreground `opencode serve` that knows its password. */
const canList = (kind: "service" | "standalone") => kind === "service" || foregroundEndpoint(process.argv, process.env) !== undefined

/** URL and auth headers of this process's own OpenCode server, when it can be reached (see src/spoke/own-server.ts). */
async function ownEndpoint(kind: "service" | "standalone"): Promise<{ url: string; headers: Record<string, string> } | undefined> {
  if (kind === "service") {
    const { Service } = await import("@opencode/client/service")
    const endpoint = await Service.discover()
    return endpoint ? { url: endpoint.url, headers: Service.headers(endpoint) ?? {} } : undefined
  }
  const endpoint = foregroundEndpoint(process.argv, process.env)
  return endpoint ? { url: endpoint.url, headers: { authorization: endpoint.authorization } } : undefined
}

/** A client for this process's own OpenCode server, when it can be reached (see src/spoke/own-server.ts). */
async function ownClient(kind: "service" | "standalone") {
  const { OpenCode } = await import("@opencode/client")
  const endpoint = await ownEndpoint(kind)
  return endpoint ? OpenCode.make({ baseUrl: endpoint.url, headers: endpoint.headers }) : undefined
}

/** The own server's client, or an error saying it cannot be reached. */
async function requireOwnClient(kind: "service" | "standalone") {
  const client = await ownClient(kind).catch(() => undefined)
  if (!client) throw new Error("This OpenCode process cannot reach its own server")
  return client
}

/** Answers or cancels a form through the own server's API (the plugin API has no forms). */
async function replyForm(kind: "service" | "standalone", action: FormAction): Promise<"replied" | "gone" | "unavailable"> {
  const client = await ownClient(kind).catch(() => undefined)
  if (!client) return "unavailable"
  try {
    if ("cancel" in action) await client.session.form.cancel({ sessionID: action.sessionID, formID: action.formID })
    else await client.session.form.reply({ sessionID: action.sessionID, formID: action.formID, answer: action.answer as Record<string, string | number | boolean | string[]> })
    return "replied"
  } catch (cause) {
    if (formOutcome(cause) === "gone") return "gone"
    throw cause
  }
}

/**
 * Has OpenCode regenerate a session's title with its title agent: session.update with an empty title over
 * the own server's HTTP API (the handler runs SessionTitle.generate and returns when it is done). The plugin
 * API's session.update would rename the session to "" instead. "unavailable" when the server cannot be reached.
 */
async function generateTitle(kind: "service" | "standalone", sessionID: string): Promise<"done" | "unavailable"> {
  const client = await ownClient(kind).catch(() => undefined)
  if (!client) return "unavailable"
  await client.session.update({ sessionID, title: "" })
  return "done"
}

/**
 * What runs now on this process's own server: session.active (sessions with a run in progress) and the running
 * shells of the given directories (shell.list, per location) that belong to a session. Empty when the server
 * cannot be reached.
 */
async function activity(kind: "service" | "standalone", directories: readonly string[]) {
  const client = await ownClient(kind).catch(() => undefined)
  if (!client) return { active: [], jobs: [] }
  const active = unwrap<Record<string, unknown>>(await client.session.active(), (v) => v && typeof v === "object" && !("data" in v))
  const jobs: Array<JobInfo & { sessionID: string }> = []
  const seen = new Set<string>()
  for (const directory of directories) {
    try {
      const list = unwrap<unknown[]>(await client.shell.list({ location: { directory } }), Array.isArray)
      for (const raw of Array.isArray(list) ? list : []) {
        const job = jobFromInfo(raw, "shell")
        if (!job?.sessionID || job.status !== "running" || seen.has(job.id)) continue
        seen.add(job.id)
        jobs.push(job as JobInfo & { sessionID: string })
      }
    } catch {
      // a location this server does not serve
    }
  }
  return { active: Object.keys(active ?? {}), jobs }
}

/**
 * What OpenCode waits for in each session on this process's own server: its pending forms (session.form.list) and
 * permission requests (session.permission.list). A session that cannot be read is left out; nothing when the
 * server cannot be reached.
 */
async function pending(kind: "service" | "standalone", sessionIDs: readonly string[]) {
  const client = await ownClient(kind).catch(() => undefined)
  if (!client) return []
  const out: Array<{ sessionID: string; forms: unknown[]; permissions: unknown[] }> = []
  // One budget for the whole listing (the spoke gives up after 5 s too): a hung server stops being asked.
  const signal = AbortSignal.timeout(PENDING_LIST_TIMEOUT_MS)
  for (const sessionID of sessionIDs) {
    if (signal.aborted) break
    try {
      const [forms, permissions] = await Promise.all([client.session.form.list({ sessionID }, { signal }), client.permission.list({ sessionID }, { signal })])
      const list = (v: unknown) => unwrap<unknown[]>(v, Array.isArray)
      out.push({ sessionID, forms: Array.isArray(list(forms)) ? list(forms) : [], permissions: Array.isArray(list(permissions)) ? list(permissions) : [] })
    } catch {
      // a session this server does not have (any more)
    }
  }
  return out
}

/** How long one listing of pending forms and permissions may take on the own server. */
const PENDING_LIST_TIMEOUT_MS = 5000

/** Plugin API results may arrive bare or wrapped as { location, data }. */
function unwrap<T>(value: unknown, isBare: (v: any) => boolean): T {
  const v = value as any
  return (v && !isBare(v) && v.data !== undefined ? v.data : v) as T
}

/** This instance's location-scoped permission API (OpenCode keeps pending permissions per location). */
function permissionLocation(ctx: Context): PermissionLocation {
  const permission = ctx.permission as any
  const vcs = (ctx as any).vcs
  const skill = (ctx as any).skill
  const command = (ctx as any).command
  return {
    directory: ctx.location.directory,
    get: (input) => permission.get(input),
    reply: (input) => permission.reply(input),
    // OpenCode's plugin vcs, skill and command lists answer for this instance's location only (whatever location is passed).
    ...(vcs?.diff && vcs?.get ? { vcs: vcsOf(vcs, ctx.location.directory) } : {}),
    ...(skill?.list && command?.list ? { names: () => localNamesOf(skill, command, ctx.location.directory) } : {}),
  }
}

/**
 * (CC-1) A directory's command or agent list: the own server's (it honours the location), else the plugin API's (it
 * answers for this instance's location).
 */
async function listAt(kind: "service" | "standalone", domain: "command" | "agent", local: any, directory: string): Promise<ReadonlyArray<unknown>> {
  const client: any = canList(kind) ? await ownClient(kind).catch(() => undefined) : undefined
  const api = client?.[domain]?.list ? client[domain] : local
  if (!api?.list) throw new Error(`This OpenCode process cannot list ${domain}s`)
  const listed = unwrap<ReadonlyArray<unknown>>(await api.list({ location: { directory } }), Array.isArray)
  return Array.isArray(listed) ? listed : []
}

/** A plugin instance's own location's skill and command names (its lists answer only for that location). */
async function localNamesOf(skill: any, command: any, directory: string) {
  const [skills, commands] = await Promise.all([skill.list({ location: { directory } }), command.list({ location: { directory } })])
  return { skills: listedNames(skills), commands: listedNames(commands) }
}

/** A vcs API's working-copy changes and current branch of a directory (plugin API or own-server client). */
function vcsOf(vcs: any, directory: string) {
  return {
    diff: async () => unwrap<ReadonlyArray<unknown>>(await vcs.diff({ mode: "working", location: { directory } }), Array.isArray),
    branch: async () => {
      const info = unwrap<{ branch?: { current?: string } }>(await vcs.get({ location: { directory } }), (v) => "branch" in v)
      return typeof info?.branch?.current === "string" ? info.branch.current : undefined
    },
  }
}

/** The own server's vcs API (it honours the location), when the server can be reached. */
function serverVcs(client: { vcs?: unknown } | undefined): VcsReader | undefined {
  if (!client?.vcs) return undefined
  return { diff: (directory) => vcsOf(client.vcs, directory).diff(), branch: (directory) => vcsOf(client.vcs, directory).branch() }
}

