/** Startup log lines about sign-in (never the client secret). Pairing mode has none. */
export function authStartupLines(config: CentralConfig): { info: string[]; warnings: string[] } {
  const auth = config.auth
  if (auth.mode !== "oidc") return { info: [], warnings: [] }
  const entries = auth.allowed.length
  const admins = auth.admins.length
  const info = [
    `multi-user: sign-in with ${auth.issuer} (client ${auth.clientId}); redirect URI ${config.publicURL}/auth/callback`,
    `multi-user: ${entries} allow-list ${entries === 1 ? "entry" : "entries"}, ${admins} admin${admins === 1 ? "" : "s"}`,
  ]
  const warnings: string[] = []
  if (!config.publicURL.startsWith("https://") && !isLoopbackURL(config.publicURL)) {
    warnings.push(`HUB_PUBLIC_URL ${config.publicURL} is not https: sign-in cookies travel unencrypted and most providers refuse the redirect URI`)
  }
  if (auth.insecureIssuer) warnings.push(`HUB_OIDC_INSECURE_ISSUER is set: plain-http issuer ${auth.issuer} allowed (development only)`)
  return { info, warnings }
}

export interface RunHubOptions {
  readonly web: WebAssets
  readonly version: string
  readonly argv?: readonly string[]
}

/** Runs the hub until SIGINT/SIGTERM (or answers --help / --version). */
export function runHub(options: RunHubOptions): void {
  const args = parseHubArgs(options.argv ?? process.argv.slice(2))
  if (args.action === "version") {
    console.log(options.version)
    return
  }
  if (args.action === "help") {
    console.log(hubHelp(options.version))
    return
  }
  if (args.action === "error") {
    console.error(`[hub] ${args.message}`)
    process.exit(2)
  }
  if (args.action === "migrate" || args.action === "import") {
    const io: CommandIO = { env: process.env, out: (line) => console.log(line), err: (line) => console.error(line) }
    const run = args.action === "import" ? runImport(args, io) : runMigrate(io)
    void run.then((code) => process.exit(code))
    return
  }

  let loaded: ReturnType<typeof loadCentralConfig>
  try {
    loaded = loadCentralConfig()
  } catch (cause) {
    console.error(`[hub] ${cause instanceof Error ? cause.message : cause}`)
    process.exit(1)
  }
  for (const warning of loaded.warnings) console.warn(`[hub] warning: ${warning}`)
  const config = loaded.config
  const central = startCentral({ config, web: options.web, version: options.version })

  console.log(`[hub] Hub ${options.version} listening on ${central.url} (public URL ${central.publicURL})`)
  console.log(`[hub] state: ${config.stateDir}`)
  console.log(`[hub] config: ${loaded.loaded ? loaded.path : `${loaded.path} (not found; using env and defaults)`}`)
  const authLines = authStartupLines(config)
  for (const line of authLines.info) console.log(`[hub] ${line}`)
  for (const line of authLines.warnings) console.warn(`[hub] warning: ${line}`)
  // (WS-B) The key ID only (a hash), never the key.
  if (config.secretsKey) console.log(`[hub] work-source credentials: encrypted at rest (key ID ${config.secretsKey.kid})`)
  const speech = central.speechSettings.view()
  if (speech.ready.reason) {
    console.log(`[hub] speech is not set up yet: ${speech.ready.reason} (or OPENROUTER_API_KEY, or speech.stt/tts in hub.json)`)
  }

  // While no device is paired, keep a fresh bootstrap pairing code in the log.
  const bootstrap = () => {
    const code = central.auth.bootstrapCode()
    if (code) console.log(`[hub] Pair your first device at ${central.publicURL}/pair with code ${code.code}`)
    return code !== undefined
  }
  let timer: ReturnType<typeof setInterval> | undefined
  if (bootstrap()) {
    timer = setInterval(() => {
      if (!bootstrap()) clearInterval(timer)
    }, PAIR_TTL_MS - 5_000)
  }

  const onSignal = shutdownOnSignals(central, {
    log: (line) => {
      clearInterval(timer)
      console.log(line)
    },
    exit: (code) => process.exit(code),
  })
  process.on("SIGTERM", () => void onSignal("SIGTERM"))
  process.on("SIGINT", () => void onSignal("SIGINT"))
}

/**
 * The hub's signal handler: the first SIGTERM/SIGINT shuts down (shutdownHub) and exits 0; a second one while that is
 * still running (a drain waiting for requests) stops at once and exits 1; later ones are ignored.
 */
export function shutdownOnSignals(
  central: { drain(): Promise<void>; stop(): Promise<void> },
  options: { readonly log: (line: string) => void; readonly exit: (code: number) => void },
): (signal: string) => Promise<void> {
  let state: "running" | "stopping" | "forced" = "running"
  return async (signal) => {
    if (state === "forced") return
    if (state === "stopping") {
      state = "forced"
      options.log(`[hub] ${signal} again: stopping now`)
      await central.stop().catch((cause: unknown) => options.log(`[hub] stop failed: ${(cause as Error)?.message ?? cause}`))
      options.exit(1)
      return
    }
    state = "stopping"
    // Once forced, the drain ending later neither stops again nor exits.
    const once = { drain: () => central.drain(), stop: () => (state === "forced" ? Promise.resolve() : central.stop()) }
    await shutdownHub(once, signal, options.log)
    if (state === "stopping") options.exit(0)
  }
}

/**
 * Shuts the hub down on a signal. SIGTERM (Kubernetes replacing the pod, systemd, docker stop) drains first (design
 * §10: /readyz fails, spokes and nodes are sent to another pod, requests in flight finish; quick without any), then
 * stops; SIGINT (Ctrl-C) stops at once. A failed drain still stops.
 */
export async function shutdownHub(central: { drain(): Promise<void>; stop(): Promise<void> }, signal: string, log: (line: string) => void = console.log): Promise<void> {
  if (signal === "SIGTERM") {
    log(`[hub] ${signal}: draining`)
    try {
      await central.drain()
    } catch (cause) {
      log(`[hub] drain failed: ${cause instanceof Error ? cause.message : cause}`)
    }
  }
  log(`[hub] ${signal}: shutting down`)
  await central.stop()
}


/** Where the one-shot commands (migrate, import) read settings and write lines. */
export interface CommandIO {
  readonly env: Readonly<Record<string, string | undefined>>
  readonly out: (line: string) => void
  readonly err: (line: string) => void
  /** For the hub.json path (default the user's home). */
  readonly home?: string
}

/**
 * The Postgres URL of the one-shot commands: HUB_DATABASE_URL, else hub.json cluster.database. Errors name the
 * setting, never the value (it holds the password).
 */
function databaseURL(io: CommandIO): string {
  const name = "HUB_DATABASE_URL (cluster.database)"
  const url = io.env.HUB_DATABASE_URL?.trim() || readHubFile(hubConfigPath(io.env, io.home ?? homedir()), io.home ?? homedir()).file?.cluster?.database
  if (!url) throw new Error(`${name} is not set: the Postgres database of the cluster`)
  let protocol: string
  try {
    protocol = new URL(url).protocol
  } catch {
    throw new Error(`${name} is not a valid URL`)
  }
  if (protocol !== "postgres:" && protocol !== "postgresql:") throw new Error(`${name} must be a postgres:// or postgresql:// URL`)
  return url
}

/** A message without the URL or its secret-ish parts (password, host). */
function redact(message: string, url: string | undefined): string {
  if (!url) return message
  let out = message.split(url).join("<database>")
  try {
    const parsed = new URL(url)
    for (const part of [parsed.password, decodeURIComponent(parsed.password), parsed.host, parsed.hostname]) {
      if (part && part.length >= 3) out = out.split(part).join("<redacted>")
    }
  } catch {
    // Not a URL: nothing more to hide.
  }
  return out
}

/** `hub-server migrate`: applies the Postgres schema (idempotent, under the advisory lock). Returns the exit code. */
export async function runMigrate(io: CommandIO & { readonly migrate?: (url: string) => Promise<MigrateResult> }): Promise<number> {
  let url: string | undefined
  try {
    url = databaseURL(io)
    const result = await (io.migrate ?? migrateDatabase)(url)
    io.out(
      result.applied.length
        ? `[hub] migrate: applied ${result.applied.join(", ")}; schema now at version ${result.version}`
        : `[hub] migrate: schema up to date at version ${result.version}`,
    )
    return 0
  } catch (cause) {
    io.err(`[hub] migrate failed: ${redact((cause as Error)?.message ?? String(cause), url)}`)
    return 1
  }
}

async function migrateDatabase(url: string): Promise<MigrateResult> {
  const sql = new SQL(url, { max: 1 })
  try {
    return await migrate(sql)
  } finally {
    await sql.close().catch(() => {})
  }
}

/**
 * `hub-server import`: the state directory into Postgres (see ./import). The report goes to stdout, or to stderr with
 * --print-token-keys, so stdout holds only the HUB_TOKEN_KEYS value. Returns the exit code (1 when a row failed).
 */
export async function runImport(
  args: ImportArgs,
  io: CommandIO & { readonly openState?: (url: string) => StateStore & { close?(): Promise<void> } },
): Promise<number> {
  const report = args.printTokenKeys ? io.err : io.out
  let url: string | undefined
  let state: (StateStore & { close?(): Promise<void> }) | undefined
  try {
    url = databaseURL(io)
    state = (io.openState ?? ((u: string) => new PostgresStateStore({ url: u, max: 2 })))(url)
    // Reachable and migrated (a schema error says to run migrate), before any row is read or counted.
    await state.ping?.()
    const result = await importState({ stateDir: args.stateDir, state, dryRun: args.dryRun, force: args.force })
    for (const line of formatImportReport(result)) report(redact(line, url))
    if (args.printTokenKeys) {
      const material = tokenKeysMaterial(args.stateDir)
      if (material) io.out(material)
      else io.err("[hub] no token-keys.json: nothing to print")
    }
    return result.failed ? 1 : 0
  } catch (cause) {
    io.err(`[hub] import failed: ${redact((cause as Error)?.message ?? String(cause), url)}`)
    return 1
  } finally {
    await state?.close?.().catch(() => {})
  }
}

// `hub claude-code <daemon | hook | mcp>`: the Claude Code spoke's own processes, run by `hub claude` (the daemon)
// and by the plugin (the hook bridge, the MCP pipe), never typed by hand in normal use.
//   daemon  the per-user daemon until SIGINT/SIGTERM (needs an enrolled machine: the machine token in the spoke's
//           config.json, read-only); with the Claude Code CLI found it also starts Claude Code for hub launches
//           (daemonLaunchOptions)
//   hook    the hook bridge (stdin: the hook's JSON; --rewake, --wait <seconds>)
//   mcp     the MCP pipe on stdio
import { spawnSync } from "node:child_process"
import { realpathSync } from "node:fs"
import { configPath } from "../../../src/config.ts"
import { nodeConfigPath, readNodeConfig, readSpokeCredentials } from "../../node/src/config.ts"
import { claudeBinary, findExecutable } from "../../node/src/harnesses.ts"
import { runHook } from "./bridge.ts"
import { startDaemon, type DaemonLaunchOptions } from "./daemon.ts"
import { runMcpPipe } from "./mcp.ts"
import { socketPath } from "./paths.ts"
import { hubPlugin, VERSION, type Program } from "./wrapper.ts"

export interface ClaudeCodeIo {
  readonly env: Readonly<Record<string, string | undefined>>
  readonly home: string
  stdout(s: string): void
  stderr(s: string): void
  readonly stdin?: () => Promise<string>
  readonly input?: AsyncIterable<Uint8Array | string>
  readonly signal?: AbortSignal
  /** What runs the hub CLI (the plugin's hooks run it); default this process (the runtime and its entry). */
  readonly program?: Program
}

export const CLAUDE_CODE_USAGE = "Usage: hub claude-code daemon | hook [--rewake] [--wait <seconds>] | mcp | install [--dry-run] | uninstall [--dry-run] | status"

/** `claude --version` → "2.1.296", or "" when it cannot be told. */
export function claudeVersion(bin: string, env: ClaudeCodeIo["env"]): string {
  try {
    const r = spawnSync(bin, ["--version"], { encoding: "utf8", timeout: 5000, env: env as NodeJS.ProcessEnv })
    return /\d+\.\d+\.\d+[\w.+-]*/.exec(r.stdout ?? "")?.[0]?.slice(0, 100) ?? ""
  } catch {
    return ""
  }
}

/**
 * How the daemon starts Claude Code for hub launches, or undefined when it does not: the Claude Code CLI must be
 * found (claudeBinary: HUB_CLAUDE_BIN, hub's claude-code.json, else `claude` on PATH) and node.json must not withhold claude-code (harnesses). Launch
 * directories must be under node.json's workspaceRoots (read again at each create); launched sessions load the hub
 * plugin `hub claude` loads (written when the first launch needs it).
 */
export function daemonLaunchOptions(io: { readonly env: ClaudeCodeIo["env"]; readonly home: string; readonly program: Program }): DaemonLaunchOptions | undefined {
  const bin = findExecutable(claudeBinary(io.env, io.home), io.env)
  if (!bin) return undefined
  const file = nodeConfigPath(io.env, io.home)
  if (readNodeConfig(file).config.harnesses?.["claude-code"] === false) return undefined
  return {
    bin,
    roots: () => readNodeConfig(file).config.workspaceRoots,
    pluginDir: () => hubPlugin(io.env, io.home, io.program),
    env: io.env,
  }
}

/** This process as the hub CLI (its runtime and entry, resolved), as `hub claude` started the daemon. */
function currentProgram(): Program {
  const entry = process.argv[1] ?? ""
  try {
    return { execPath: process.execPath, entry: realpathSync(entry) }
  } catch {
    return { execPath: process.execPath, entry }
  }
}

async function daemon(io: ClaudeCodeIo): Promise<number> {
  const credentials = readSpokeCredentials(io.env, io.home)
  if (!credentials) {
    io.stderr(`hub claude-code daemon: this machine is not enrolled with a hub (no machine token in ${configPath(io.env, io.home)})\n`)
    return 1
  }
  const log = (line: string) => io.stderr(`[hub claude-code] ${new Date().toISOString()} ${line}\n`)
  const launch = daemonLaunchOptions({ env: io.env, home: io.home, program: io.program ?? currentProgram() })
  let running
  try {
    running = await startDaemon({
      socketPath: socketPath(io.env, io.home),
      server: credentials.server,
      token: credentials.token,
      harnessVersion: claudeVersion(claudeBinary(io.env, io.home), io.env),
      pluginVersion: VERSION,
      directory: io.home,
      log,
      ...(launch ? { launch } : {}),
    })
  } catch (cause) {
    io.stderr(`hub claude-code daemon: ${cause instanceof Error ? cause.message : String(cause)}\n`)
    return 1
  }
  log(`listening on ${socketPath(io.env, io.home)}; ${launch ? `starts ${launch.bin} for hub launches` : "no hub launches (Claude Code CLI not found, or node.json withholds claude-code)"}`)
  await new Promise<void>((resolve) => {
    if (!io.signal) return
    if (io.signal.aborted) return resolve()
    io.signal.addEventListener("abort", () => resolve(), { once: true })
  })
  await running.stop()
  return 0
}

export async function claudeCodeMain(argv: readonly string[], io: ClaudeCodeIo): Promise<number> {
  const [command, ...rest] = argv
  switch (command) {
    case "hook": {
      const stdin = io.stdin ? await io.stdin().catch(() => "") : ""
      return runHook({ argv: rest, stdin, env: io.env, socketPath: socketPath(io.env, io.home), stdout: io.stdout, stderr: io.stderr })
    }
    case "mcp":
      if (!io.input) {
        io.stderr("hub claude-code mcp: needs stdin\n")
        return 2
      }
      await runMcpPipe({ input: io.input, write: io.stdout, socketPath: socketPath(io.env, io.home), env: io.env, version: VERSION, ...(io.signal ? { signal: io.signal } : {}) })
      return 0
    case "daemon":
      return daemon(io)
    default:
      io.stderr(`${CLAUDE_CODE_USAGE}\n`)
      return 2
  }
}

// The plugin directory `hub claude` loads with --plugin-dir (decision fx04e42c point 4: never the user's ~/.claude
// files). hooks/hooks.json runs the hook bridge (`hub claude-code hook`) for every event the spoke uses, with the
// absolute runtime and CLI entry quoted for sh and nothing else from outside in the command; PermissionRequest
// passes the permission wait (--wait <s>) under a hook timeout 2 s above it (the spike: wait ≤ hook timeout − 1 s);
// Stop also runs an asyncRewake bridge (--rewake) that blocks until the daemon has a message to wake the idle
// session with (exit 2). .mcp.json runs the daemon-backed MCP pipe. Each configuration gets its own directory
// (plugin-<hash>), written once.
import { createHash } from "node:crypto"
import { existsSync, mkdirSync, renameSync, rmSync, writeFileSync } from "node:fs"
import path from "node:path"
import { ensurePrivateDir } from "./paths.ts"

export interface PluginOptions {
  /** What runs the hub CLI: the runtime and the CLI's entry file (absolute paths). */
  readonly program: { readonly execPath: string; readonly entry: string }
  /** How long a PermissionRequest waits for the hub (0: report only, the local dialog decides). */
  readonly permissionWaitS: number
  /** How long the asyncRewake Stop hook may wait for a message. */
  readonly rewakeTimeoutS: number
  readonly version: string
}

/** The hook events the spoke registers. */
export const HOOK_EVENTS: readonly string[] = [
  "SessionStart",
  "UserPromptSubmit",
  "PreToolUse",
  "PostToolUse",
  "PostToolUseFailure",
  "PermissionRequest",
  "PermissionDenied",
  "Notification",
  "Stop",
  "StopFailure",
  "SubagentStart",
  "SubagentStop",
  "SessionEnd",
]
/** Events with a tool matcher. */
const TOOL_EVENTS: ReadonlySet<string> = new Set(["PreToolUse", "PostToolUse", "PostToolUseFailure", "PermissionRequest", "PermissionDenied"])
/** Timeout of the hooks that only report (seconds): the daemon answers at once. SessionStart waits for a token. */
const REPORT_TIMEOUT_S = 10
const SESSION_START_TIMEOUT_S = 15
const PERMISSION_SLACK_S = 2

/** An absolute path without quotes or control characters (safe single-quoted for sh); refused otherwise. */
function checked(p: string): string {
  if (!path.isAbsolute(p) || /['\u0000-\u001f\u007f]/.test(p)) throw new Error(`Cannot use ${JSON.stringify(p)} in a hook command: it must be an absolute path without quotes or control characters`)
  return p
}

const quoted = (p: string) => `'${checked(p)}'`

const json = (value: unknown) => `${JSON.stringify(value, null, 2)}\n`

/** The plugin's files (relative path → content). */
export function pluginFiles(options: PluginOptions): Record<string, string> {
  const { execPath, entry } = options.program
  const bridge = `BUN_BE_BUN=1 ${quoted(execPath)} ${quoted(entry)} claude-code hook`
  const wait = Math.max(0, Math.round(options.permissionWaitS))
  const command = (cmd: string, timeout: number, extra: Record<string, unknown> = {}) => ({ type: "command", command: cmd, ...extra, timeout })
  const hooks: Record<string, unknown[]> = {}
  for (const event of HOOK_EVENTS) {
    const list =
      event === "PermissionRequest"
        ? [command(`${bridge} --wait ${wait}`, wait > 0 ? wait + PERMISSION_SLACK_S : REPORT_TIMEOUT_S)]
        : event === "Stop"
          ? [command(bridge, REPORT_TIMEOUT_S), command(`${bridge} --rewake`, Math.max(1, Math.round(options.rewakeTimeoutS)), { asyncRewake: true })]
          : [command(bridge, event === "SessionStart" ? SESSION_START_TIMEOUT_S : REPORT_TIMEOUT_S)]
    hooks[event] = [{ ...(TOOL_EVENTS.has(event) ? { matcher: "*" } : {}), hooks: list }]
  }
  return {
    ".claude-plugin/plugin.json": json({ name: "hub", version: options.version, description: "Hub: follow, message and steer this Claude Code session from the hub (hooks spoke)" }),
    "hooks/hooks.json": json({ hooks }),
    ".mcp.json": json({ mcpServers: { hub: { command: checked(execPath), args: [checked(entry), "claude-code", "mcp"], env: { BUN_BE_BUN: "1" } } } }),
  }
}

/** Writes the plugin for `options` under `base` (once: plugin-<hash>) and returns its directory. */
export function writePlugin(base: string, options: PluginOptions): string {
  const files = pluginFiles(options)
  const hash = createHash("sha256").update(JSON.stringify(files)).digest("hex").slice(0, 12)
  ensurePrivateDir(base)
  const dir = path.join(base, `plugin-${hash}`)
  if (existsSync(path.join(dir, "hooks", "hooks.json"))) return dir
  const tmp = `${dir}.tmp-${process.pid}-${Date.now()}`
  for (const [file, content] of Object.entries(files)) {
    mkdirSync(path.dirname(path.join(tmp, file)), { recursive: true, mode: 0o700 })
    writeFileSync(path.join(tmp, file), content, { mode: 0o600 })
  }
  try {
    renameSync(tmp, dir)
  } catch (cause) {
    rmSync(tmp, { recursive: true, force: true })
    if (!existsSync(dir)) throw cause // another run wrote it first otherwise
  }
  ensurePrivateDir(dir)
  return dir
}

