function reportError(io: Io, error: CliError, json: boolean) {
  if (json && error.envelope) printJSON(io, { error: error.envelope })
  io.stderr(`hub: ${error.message}\n`)
  const envelope = error.envelope
  const candidates = envelope?.candidates
  if (Array.isArray(candidates) && candidates.length) {
    io.stderr("candidates:\n")
    for (const c of candidates as { sessionID?: string; name?: string; title?: string }[]) {
      io.stderr(`  ${[c.sessionID, c.name ? `@${String(c.name).replace(/^@/, "")}` : undefined, c.title].filter(Boolean).join("  ")}\n`)
    }
  }
  if (typeof envelope?.feature === "string") io.stderr(`missing feature: ${envelope.feature}${typeof envelope.harness === "string" ? ` (${envelope.harness})` : ""}\n`)
  if (envelope?.code === "needs_user") for (const line of needsUserLines(envelope)) io.stderr(`${line}\n`)
  if (typeof envelope?.retryAfter === "number") io.stderr(`retry after ${Math.ceil(envelope.retryAfter)} s\n`)
  if (error.hint) io.stderr(`hint: ${error.hint}\n`)
}

export async function run(argv: string[], io: Io): Promise<number> {
  const [name, ...rest] = argv
  if (name === undefined) {
    io.stderr(`${USAGE}\n`)
    return EXIT.usage
  }
  if (name === "help" || name === "--help" || name === "-h") {
    out(io, USAGE)
    return EXIT.ok
  }
  if (name === "--version" || name === "-V" || name === "version") {
    out(io, VERSION)
    return EXIT.ok
  }
  // `hub claude` passes every other argument to Claude Code; `hub claude-code` has its own subcommands.
  if (name === "claude") return runClaude(rest, { env: io.env, home: io.home, stderr: io.stderr, program: io.program ?? currentProgram() })
  // Their service verbs (install, uninstall, status) are commands of this CLI, like `hub node install`.
  if (name === "claude-code" && !isServiceVerb(rest[0])) return claudeCodeMain(rest, io)
  if (name === "preset") return presetMain(rest, io)
  // `hub codex` passes every other argument to Codex; `hub codex-spoke serve` is the spoke service it starts.
  if (name === "codex") return runCodex(rest, { env: io.env, home: io.home, stderr: io.stderr, program: io.program ?? currentProgram() })
  if (name === "codex-spoke" && !isServiceVerb(rest[0])) return codexMain(rest, io)
  // `hub watchlist` alone (or with only flags) shows it.
  if (name === "watchlist" && (rest[0] === undefined || rest[0].startsWith("-"))) rest.unshift("show")
  let label = name
  // Groups nest (`hub node openshell check`): each level picks one of its sub-verbs.
  for (let verbs = groupVerbs(label); verbs; verbs = groupVerbs(label)) {
    const verb = rest.shift()
    if (verb === "--help" || verb === "-h") {
      out(io, USAGE)
      return EXIT.ok
    }
    if (verb === undefined || !verbs.includes(verb)) {
      io.stderr(`hub ${label}: ${verb === undefined ? "needs" : `unknown subcommand ${verb}; use`} ${verbs.join(" or ")}\n`)
      return EXIT.usage
    }
    label = `${label} ${verb}`
  }
  const command = COMMANDS[label]
  if (!command) {
    io.stderr(`hub: unknown command ${name}\nRun \`hub help\` for the commands.\n`)
    return EXIT.usage
  }
  let json = false
  try {
    const parsed = parse(rest, command)
    if (parsed.flags.help) {
      out(io, USAGE)
      return EXIT.ok
    }
    json = parsed.flags.json === true
    let warned = false
    const credentials = () => {
      const found = resolveCredentials(io.env, io.home)
      if (!found) throw notLoggedIn(io, label)
      // A stored login on a plain-http, non-loopback hub (--allow-insecure-http, or an older login): every command
      // says so, once, on stderr (never in --json output).
      if (found.source === "login" && !warned && isInsecureStoredURL(found.url)) {
        warned = true
        io.stderr(`hub: warning: ${storedInsecureWarning(found.url)}\n`)
      }
      return found
    }
    return (await command.handle({ io, parsed, json, credentials, hub: (use) => withHub(credentials(), use) })) ?? EXIT.ok
  } catch (cause) {
    if (cause instanceof UsageError) {
      io.stderr(`hub ${label}: ${cause.message}\nRun \`hub help\` for usage.\n`)
      return EXIT.usage
    }
    if (cause instanceof CliError) {
      reportError(io, cause, json)
      return cause.exit
    }
    io.stderr(`hub: ${cause instanceof Error ? cause.message : String(cause)}\n`)
    return EXIT.other
  }
}

#!/usr/bin/env bun
// Entry of the hub CLI (`hub` / `hubctl`, one command surface): the npm bundle the spoke's launchers run as
// `BUN_BE_BUN=1 <opencode binary> hub-cli.js …` (or node), and the standalone hubctl (`bun build --compile` of this
// file; scripts/build-hubctl.sh). See cli.ts for the program.
import { homedir } from "node:os"
import { createInterface } from "node:readline"
import { run } from "./cli"

// The launcher sets BUN_BE_BUN so the OpenCode binary acts as bun; nothing this process starts may inherit it.
delete process.env.BUN_BE_BUN

const argv = process.argv.slice(2)

/** All of stdin when piped; a prompted line on a terminal (`hub login` without --token). */
async function stdin(): Promise<string> {
  if (!process.stdin.isTTY) {
    const chunks: Buffer[] = []
    for await (const chunk of process.stdin) chunks.push(Buffer.from(chunk))
    return Buffer.concat(chunks).toString("utf8")
  }
  const rl = createInterface({ input: process.stdin, output: process.stderr, terminal: true })
  try {
    return await new Promise<string>((resolve) => rl.question("App token: ", resolve))
  } finally {
    rl.close()
  }
}

// Only `watch`, `mcp` and `node run` run until interrupted: SIGINT/SIGTERM end them cleanly (exit 0; the service
// units stop the node with SIGTERM); other commands keep the default.
const nodeRun = argv[0] === "node" && argv[1] === "run"
// `hub claude-code daemon` and `hub claude-code mcp` (the Claude Code spoke) run until interrupted too.
const claudeDaemon = argv[0] === "claude-code" && argv[1] === "daemon"
const claudeMcp = argv[0] === "claude-code" && argv[1] === "mcp"
// `hub codex-spoke serve` (the Codex spoke service) and `hub preset run` (until its pane ends) too.
const codexServe = argv[0] === "codex-spoke" && argv[1] === "serve"
const presetRun = argv[0] === "preset" && argv[1] === "run"
// `hubctl machine enroll` and `hub login` (device code) poll until the code is approved: Ctrl-C cancels them (exit 4,
// nothing stored). `hubctl setup apply` / `recover` pass the signal to their probes and the verification launch, so
// Ctrl-C fails the running step and the transaction rolls back, instead of the process dying between a write and its
// journal entry. `setup verify` passes it to its probes too: they lead their own process group (process-tree.ts), so
// the terminal's Ctrl-C reaches them only through this signal, which ends each probe's whole tree.
const enroll = (argv[0] === "machine" && argv[1] === "enroll") || argv[0] === "login"
const applying = argv[0] === "setup" && (argv[1] === "apply" || argv[1] === "recover" || argv[1] === "verify")
const controller = new AbortController()
if (argv[0] === "watch" || argv[0] === "mcp" || nodeRun || claudeDaemon || claudeMcp || codexServe || presetRun || enroll || applying)
  for (const signal of ["SIGINT", "SIGTERM"] as const) process.once(signal, () => controller.abort())

process.exitCode = await run(argv, {
  env: process.env,
  home: homedir(),
  stdout: (s) => process.stdout.write(s),
  stderr: (s) => process.stderr.write(s),
  stdin,
  stdinIsTerminal: process.stdin.isTTY === true,
  signal: controller.signal,
  input: process.stdin,
  cwd: process.cwd(),
})
// A signal ends `hub mcp` with its stdin still open; let go of it so the process can exit.
if (argv[0] === "mcp" || claudeMcp) process.stdin.destroy()
// Nothing else (sockets, timers) may keep a stopped node, Claude Code daemon or Codex spoke alive, nor `hub claude` /
// `hub codex` once the harness exited, nor a stopped `hub preset run`.
if (nodeRun || claudeDaemon || codexServe || argv[0] === "claude" || argv[0] === "codex" || presetRun) process.exit()

// @huynle/hub-codex: the Codex app-server spoke (design §1.2, §13.3; decision fx04e42c point 5 as corrected by the
// P7-T0 spike, report v0hsdqhm). The spoke attaches to Codex's app-server as one of its clients: its own
// `codex app-server` over stdio for the sessions it starts, and the shared daemon's socket when present (the TUI's
// threads live there). `hub codex` runs the Codex TUI so its threads land on the daemon.
export * from "./ids.ts"
export * from "./jsonrpc.ts"
export * from "./stdio.ts"
export * from "./websocket.ts"
export * from "./sessions.ts"
export * from "./app-server.ts"
export * from "./spoke.ts"

// `hub codex-spoke serve`: the per-user Codex spoke service until SIGINT/SIGTERM (main.ts aborts io.signal), started
// in the background by `hub codex` and never typed by hand in normal use. It needs an enrolled machine (the machine
// token in the spoke's config.json, read-only), keeps a pid file in <hub state dir>/codex/spoke.pid (one service per
// user: a second one refuses while the first runs) and attaches to the shared Codex daemon's socket when present.
//
// Settings (environment): HUB_CODEX_BIN (default: the Codex `hubctl setup` installed, else `codex` on PATH), HUB_CODEX_DAEMON_SOCKET (another socket, or
// "off"), HUB_CODEX_CONFIG (Codex config overrides for the app-server the spoke starts, one key=value per line,
// passed as -c; Codex's files are never written).
import { spawnSync } from "node:child_process"
import { openSync, closeSync, readFileSync, rmSync, writeSync } from "node:fs"
import { configPath } from "../../../src/config.ts"
import { readSpokeCredentials } from "../../node/src/config.ts"
import { codexBinary } from "../../node/src/harnesses.ts"
import pkg from "../package.json" with { type: "json" }
import { codexStateDir, ensurePrivateDir, daemonSocketPath, pidFile, readServicePid } from "./paths.ts"
import { startCodexSpoke } from "./spoke.ts"

export const VERSION: string = pkg.version

export interface CodexMainIo {
  readonly env: Readonly<Record<string, string | undefined>>
  readonly home: string
  stdout(s: string): void
  stderr(s: string): void
  readonly signal?: AbortSignal
}

export const CODEX_SPOKE_USAGE = "Usage: hub codex-spoke serve | install [--dry-run] | uninstall [--dry-run] | status"

/** `codex --version` → "0.160.0", or "" when it cannot be told. */
export function codexVersion(bin: string, env: CodexMainIo["env"]): string {
  try {
    const r = spawnSync(bin, ["--version"], { encoding: "utf8", timeout: 5000, env: env as NodeJS.ProcessEnv })
    return /\d+\.\d+\.\d+[\w.+-]*/.exec(r.stdout ?? "")?.[0]?.slice(0, 100) ?? ""
  } catch {
    return ""
  }
}

/** HUB_CODEX_CONFIG's lines as `-c key=value` arguments. */
export function configOverrides(value: string | undefined): string[] {
  return (value ?? "")
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line !== "" && line.includes("="))
    .flatMap((line) => ["-c", line])
}

/** Claims the pid file for this process; false when another live service holds it. */
function claimPidFile(file: string, env: CodexMainIo["env"], home: string): boolean {
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const fd = openSync(file, "wx", 0o600)
      try {
        writeSync(fd, `${process.pid}\n`)
      } finally {
        closeSync(fd)
      }
      return true
    } catch (cause) {
      if ((cause as NodeJS.ErrnoException).code !== "EEXIST") throw cause
      if (readServicePid(env, home) !== undefined) return false
      rmSync(file, { force: true }) // a stale file: its process is gone
    }
  }
  return false
}

function releasePidFile(file: string): void {
  try {
    if (readFileSync(file, "utf8").trim() === String(process.pid)) rmSync(file, { force: true })
  } catch {}
}

async function serve(io: CodexMainIo): Promise<number> {
  const credentials = readSpokeCredentials(io.env, io.home)
  if (!credentials) {
    io.stderr(`hub codex-spoke serve: this machine is not enrolled with a hub (no machine token in ${configPath(io.env, io.home)})\n`)
    return 1
  }
  const log = (line: string) => io.stderr(`[hub codex-spoke] ${new Date().toISOString()} ${line}\n`)
  ensurePrivateDir(codexStateDir(io.env, io.home))
  const file = pidFile(io.env, io.home)
  if (!claimPidFile(file, io.env, io.home)) {
    io.stderr(`hub codex-spoke serve: already running (pid ${readServicePid(io.env, io.home) ?? "?"})\n`)
    return 1
  }
  try {
    const codexBin = codexBinary(io.env, io.home)
    const env: Record<string, string | undefined> = { ...io.env }
    delete env.BUN_BE_BUN
    const daemonSocket = daemonSocketPath(io.env, io.home)
    const running = startCodexSpoke({
      server: credentials.server,
      token: credentials.token,
      harnessVersion: codexVersion(codexBin, env),
      pluginVersion: VERSION,
      directory: io.home,
      codexBin,
      codexArgs: configOverrides(io.env.HUB_CODEX_CONFIG),
      env,
      ...(daemonSocket ? { daemonSocket } : {}),
      log,
    })
    log(daemonSocket ? `serving; the Codex daemon socket is ${daemonSocket}` : "serving; not attaching to a Codex daemon")
    await new Promise<void>((resolve) => {
      if (!io.signal) return
      if (io.signal.aborted) return resolve()
      io.signal.addEventListener("abort", () => resolve(), { once: true })
    })
    await running.stop()
    return 0
  } finally {
    releasePidFile(file)
  }
}

export async function codexMain(argv: readonly string[], io: CodexMainIo): Promise<number> {
  const [command] = argv
  if (command === "serve") return serve(io)
  io.stderr(`${CODEX_SPOKE_USAGE}\n`)
  return 2
}

#!/usr/bin/env bun
// Entry of `hub node`: `bun packages/node/src/main.ts` (what the launchd and systemd units run), or the same file
// bundled for node. SIGINT and SIGTERM stop the daemon cleanly (exit 0). See run.ts for the program.
import { runNode } from "./run.ts"

const controller = new AbortController()
for (const signal of ["SIGINT", "SIGTERM"] as const) process.once(signal, () => controller.abort())

process.exitCode = await runNode({ signal: controller.signal })
// Nothing else (sockets, timers) may keep a stopped node alive.
process.exit()

// `hub preset <list | check | run>`: the preset spoke's command line.
//   list                        the official presets
//   check <name|file>           validate a preset (presetProblem); exit 1 when it is not valid
//   run <name|file> [options] [-- harness args…]
//       starts the preset's command (an argv, never through a shell) in a new tmux pane and connects it to the hub
//       as a preset spoke (evidence screen) until the pane ends or Ctrl-C/SIGTERM (which leaves the harness running).
//       --socket <name>   the private tmux server (`tmux -L <name>`, default hub-preset): the user's own tmux server
//                         is never touched, unless
//       --current         a new window in the tmux session this runs in ($TMUX), only when asked
//       --cwd <dir>       the harness's directory (default the current one)
//       --resume <id>     resume a native session (the preset's resumeFlag)
//       --no-hub          only start the pane and report it (no hub connection; no enrolment needed)
// The native session ID is reported as the spoke knows it: passed on the command line or resumed ("reported, not
// observed"), or read off the screen once it shows.
import path from "node:path"
import { readSpokeCredentials } from "../../node/src/config.ts"
import { configPath } from "../../../src/config.ts"
import pkg from "../package.json" with { type: "json" }
import { findPreset, OFFICIAL_PRESETS } from "./presets.ts"
import { PresetSpoke } from "./spoke.ts"
import { tmuxBackend, tmuxRunner, type TerminalBackend, type TmuxRunner } from "./tmux.ts"

export interface PresetIo {
  readonly env: Readonly<Record<string, string | undefined>>
  readonly home: string
  /** The working directory (default process.cwd()). */
  readonly cwd?: string
  stdout(s: string): void
  stderr(s: string): void
  /** Ends `run` (main.ts aborts it on SIGINT/SIGTERM). */
  readonly signal?: AbortSignal
  /** Runs tmux (default the `tmux` on PATH). */
  readonly tmux?: TmuxRunner
  readonly newID?: () => string
  /** How often the pane is sampled (default the spoke's). */
  readonly sampleMs?: number
}

export const PRESET_USAGE = `Usage: hub preset list
       hub preset check <name|file>
       hub preset run <name|file> [--socket <name> | --current] [--cwd <dir>] [--resume <id>] [--no-hub] [-- harness args…]`

export const DEFAULT_SOCKET = "hub-preset"

interface RunArgs {
  readonly ref: string
  readonly socket?: string
  readonly current: boolean
  readonly cwd?: string
  readonly resume?: string
  readonly noHub: boolean
  readonly args: string[]
}

function parseRun(argv: readonly string[]): RunArgs | { error: string } {
  const dash = argv.indexOf("--")
  const own = dash >= 0 ? argv.slice(0, dash) : [...argv]
  const args = dash >= 0 ? argv.slice(dash + 1) : []
  let ref: string | undefined
  const values: Record<string, string> = {}
  const flags = new Set<string>()
  for (let i = 0; i < own.length; i++) {
    const arg = own[i]!
    if (arg === "--socket" || arg === "--cwd" || arg === "--resume") {
      const value = own[++i]
      if (value === undefined || value.startsWith("--")) return { error: `${arg} needs a value` }
      values[arg] = value
    } else if (arg === "--current" || arg === "--no-hub") flags.add(arg)
    else if (arg.startsWith("-")) return { error: `unknown option ${arg} (harness arguments go after --)` }
    else if (ref === undefined) ref = arg
    else return { error: `unexpected ${JSON.stringify(arg)} (harness arguments go after --)` }
  }
  if (ref === undefined) return { error: "run needs a preset name or file" }
  if (flags.has("--current") && values["--socket"] !== undefined) return { error: "--current and --socket exclude each other" }
  return {
    ref,
    current: flags.has("--current"),
    noHub: flags.has("--no-hub"),
    args,
    ...(values["--socket"] !== undefined ? { socket: values["--socket"] } : {}),
    ...(values["--cwd"] !== undefined ? { cwd: values["--cwd"] } : {}),
    ...(values["--resume"] !== undefined ? { resume: values["--resume"] } : {}),
  }
}

const message = (e: unknown) => (e instanceof Error ? e.message : String(e))

async function run(argv: readonly string[], io: PresetIo): Promise<number> {
  const parsed = parseRun(argv)
  if ("error" in parsed) {
    io.stderr(`hub preset: ${parsed.error}\n${PRESET_USAGE}\n`)
    return 2
  }
  const cwd = io.cwd ?? process.cwd()
  const found = findPreset(parsed.ref, { cwd })
  if ("error" in found) {
    io.stderr(`hub preset: ${found.error}\n`)
    return 1
  }
  const preset = found.preset
  if (parsed.resume !== undefined && !preset.resumeFlag) {
    io.stderr(`hub preset: the ${preset.name} preset cannot resume a session (it has no resumeFlag)\n`)
    return 1
  }
  let backend: TerminalBackend
  try {
    backend = tmuxBackend({
      ...(parsed.current ? { current: true } : { socket: parsed.socket ?? DEFAULT_SOCKET }),
      env: io.env,
      run: io.tmux ?? tmuxRunner("tmux", io.env as NodeJS.ProcessEnv),
    })
  } catch (cause) {
    io.stderr(`hub preset: ${message(cause)}\n`)
    return 1
  }
  const credentials = parsed.noHub ? undefined : readSpokeCredentials(io.env, io.home)
  if (!parsed.noHub && !credentials) {
    io.stderr(`hub preset: this machine is not enrolled with a hub (no machine token in ${configPath(io.env, io.home)}); use --no-hub to only start the pane\n`)
    return 1
  }
  const log = (line: string) => io.stderr(`[hub preset] ${line}\n`)
  const spoke = new PresetSpoke({
    preset,
    backend,
    server: credentials?.server ?? "http://127.0.0.1:1",
    token: credentials?.token ?? "",
    pluginVersion: pkg.version,
    directory: cwd,
    ...(io.newID ? { newID: io.newID } : {}),
    ...(io.sampleMs !== undefined ? { sampleMs: io.sampleMs } : {}),
    log,
    onState: (state, error) => log(`hub connection ${state}${error ? `: ${error}` : ""}`),
  })
  if (credentials) spoke.start()
  let launched
  try {
    launched = await spoke.launch({ cwd: parsed.cwd ? path.resolve(cwd, parsed.cwd) : cwd, args: parsed.args, ...(parsed.resume !== undefined ? { resume: parsed.resume } : {}) })
  } catch (cause) {
    spoke.stop()
    io.stderr(`hub preset: ${message(cause)}\n`)
    return 1
  }
  const where = parsed.current ? "the current tmux session" : `tmux session ${launched.pane.session} on socket ${parsed.socket ?? DEFAULT_SOCKET}`
  const native = launched.nativeID
    ? `${launched.nativeID.id} (${launched.nativeID.how})`
    : preset.nativeID.source === "screen"
      ? "not seen yet (read off the screen when it shows)"
      : `none (the ${preset.name} preset has no session IDs)`
  const lines = [
    `started ${preset.name} in ${where}${parsed.current ? ` (window ${launched.pane.window})` : ""}, pane ${launched.pane.target}`,
    credentials ? `session: ${launched.sessionID} (evidence screen: hub messages are pasted, never confirmed)` : "not connected to a hub (--no-hub): the pane runs on its own",
    `native ID: ${native}`,
    `attach: ${launched.attach}`,
  ]
  io.stdout(`${lines.join("\n")}\n`)
  if (!credentials) return 0

  const outcome = await new Promise<"ended" | "signal">((resolve) => {
    spoke.onEnd((id) => id === launched.sessionID && resolve("ended"))
    if (io.signal?.aborted) return resolve("signal")
    io.signal?.addEventListener("abort", () => resolve("signal"), { once: true })
  })
  spoke.stop()
  io.stdout(outcome === "ended" ? `${preset.name} ended (its pane is gone)\n` : `disconnected from the hub; ${preset.name} is still running in its pane (attach: ${launched.attach})\n`)
  return 0
}

export async function presetMain(argv: readonly string[], io: PresetIo): Promise<number> {
  const [command, ...rest] = argv
  switch (command) {
    case "list": {
      const width = Math.max(...OFFICIAL_PRESETS.map((p) => p.name.length))
      io.stdout(`${OFFICIAL_PRESETS.map((p) => `${p.name.padEnd(width)}  ${p.description ?? ""}`.trimEnd()).join("\n")}\n`)
      return 0
    }
    case "check": {
      if (rest.length !== 1) {
        io.stderr(`hub preset: check needs one preset name or file\n${PRESET_USAGE}\n`)
        return 2
      }
      const found = findPreset(rest[0]!, { cwd: io.cwd ?? process.cwd() })
      if ("error" in found) {
        io.stderr(`hub preset: ${found.error}\n`)
        return 1
      }
      io.stdout(`${found.preset.name}: a valid preset (${found.source === "official" ? "official" : found.source})\n`)
      return 0
    }
    case "run":
      return run(rest, io)
    default:
      io.stderr(`${PRESET_USAGE}\n`)
      return 2
  }
}

// Central server ↔ spoke protocol, version 1. JSON text frames over a WebSocket at /spoke/ws.
// A spoke (a harness plugin; OpenCode first) connects outbound with `Authorization: Bearer <machineToken>`.
// Every frame is one object with a `t` discriminator. Unknown or malformed frames are rejected.
//
// Core and features: the core ops (CORE_OPS: turn, steer, interrupt, stop, permission, form) and the optional
// features a spoke announces in its hello (SPOKE_FEATURES); the hub uses only what a spoke serves (spokeFeatures).
// An OpenCode spoke (a hello without `harness` or with harness "opencode") serves every core op without announcing
// it; any other harness announces the core ops it serves, like any feature. A hello without `harness` comes from an
// OpenCode spoke that predates this split and also implies IMPLIED_OPENCODE_FEATURES. The hub announces its own features in the welcome (HUB_FEATURES), and a spoke
// sends a newer request only when the hub listed it. Neither side bumps PROTOCOL_VERSION for a new feature.
//
// Modules: harness-events.ts (the forwarded events a non-OpenCode spoke may send, with their shapes), launch.ts
// (launch vocabulary and workspace checks), node.ts (the `hub node` hello, frames and ops on the same socket),
// preset.ts (the harness preset schema), webhook.ts (webhook signature format), wire.ts (shared frame primitives).
// Workspaces/artifacts/teams contracts (HWA-02, docs/plans/2026-10-30-hub-workspaces-artifacts-contracts.md):
// contracts.ts (shared IDs, limits, revisions), hub-workspace.ts, profiles.ts, artifacts.ts, teams.ts, graph.ts.
// The versioned HTTP API (docs/plans/2026-11-12-api-v1-contract-and-native-app-design.md): api-v1.ts.
// All are re-exported here.

import { featureList, HUB_URL_MAX_CHARS, ID, isByeFrame as isBye, isHubURL, isObj, isResFrame as isRes, isWelcomeFrame, MAX_FRAME, MAX_RETRY_AFTER_MS, nonEmpty, num, parseFrame as parse, str, token, UNSAFE_CHARS } from "./wire.ts"
import type { NodeMessage, NodeServerMessage } from "./node.ts"
import { isWindowsAbsolutePath } from "./launch.ts"
import { PROFILE_APPLY_FEATURE, profileApplyRequestProblem, type ProfileApplyRequest, type ProfileApplyResult } from "./profiles.ts"
import { SESSION_CONTEXT_FEATURE, sessionContextProblem, type SessionContextRequest, type SessionContextResult } from "./concierge.ts"
