/** A committed revert's window as a spoke reports it. */
export function isRevertCommitted(v: unknown): v is RevertCommitted {
  return isObj(v) && nonEmpty(v.messageID) && v.messageID.length <= 300 && (v.from === undefined || num(v.from)) && num(v.until) && num(v.at)
}

