/** The child session a subagent tool reports in its metadata (`{sessionID: "ses_…"}`). */
function childSessionOf(metadata: unknown): string | undefined {
  const id = (metadata as { sessionID?: unknown } | undefined)?.sessionID
  return typeof id === "string" && /^ses_[A-Za-z0-9]+$/.test(id) ? id : undefined
}

const JOB_EVENTS = new Set(["session.shell.started", "session.shell.ended", "shell.created", "shell.exited", "shell.deleted", "pty.created", "pty.updated", "pty.exited", "pty.deleted"])
const JOB_STATUSES = new Set<string>(["running", "exited", "timeout", "killed"])

function clipText(value: unknown, max: number): string | undefined {
  if (typeof value !== "string") return undefined
  const line = value.replace(/\s+/g, " ").trim()
  if (!line) return undefined
  return line.length > max ? `${line.slice(0, max - 1)}…` : line
}

const finite = (v: unknown): number | undefined => (typeof v === "number" && Number.isFinite(v) ? v : undefined)

const errorType = (v: unknown): string | undefined => (typeof v === "string" && v.length > 0 && v.length <= ERROR_TYPE_MAX ? v : undefined)
const httpStatus = (v: unknown): number | undefined => (Number.isInteger(v) && (v as number) >= 100 && (v as number) <= 599 ? (v as number) : undefined)

/** OpenCode's SessionStatus reduced to its type and (retry) attempt, short reason, next try and error kind. */
export function compactStatus(raw: unknown): CompactSessionStatus | undefined {
  const status = raw as Record<string, unknown> | null
  if (!status || typeof status !== "object") return undefined
  if (status.type === "idle" || status.type === "busy") return { type: status.type }
  if (status.type !== "retry") return undefined
  const attempt = finite(status.attempt)
  const message = clipText(status.message, RETRY_MESSAGE_MAX)
  const next = finite(status.next)
  const type = errorType(status.errorType)
  const code = httpStatus(status.errorStatus)
  return {
    type: "retry",
    ...(attempt !== undefined ? { attempt } : {}),
    ...(message ? { message } : {}),
    ...(next !== undefined ? { next } : {}),
    ...(type ? { errorType: type } : {}),
    ...(code !== undefined ? { errorStatus: code } : {}),
  }
}

/** An OpenCode run error ({type, message, status?, response?, retryAfterMs?}) as its message, type and status only. */
export function compactRunError(raw: unknown): CompactRunError | undefined {
  const error = raw as Record<string, unknown> | null
  if (!error || typeof error !== "object") return undefined
  const message = typeof error.message === "string" && error.message.trim() ? error.message.trim().slice(0, ERROR_MESSAGE_MAX) : "failed"
  const type = errorType(error.type)
  const status = httpStatus(error.status)
  return { message, ...(type ? { type } : {}), ...(status !== undefined ? { status } : {}) }
}

/** OpenCode 2.2's session.retry.scheduled as the session.status retry every hub accepts. */
function compactRetry(d: Record<string, unknown>): ForwardedEvent | undefined {
  if (typeof d.sessionID !== "string" || !d.sessionID) return undefined
  const error = (d.error && typeof d.error === "object" ? d.error : {}) as Record<string, unknown>
  const status = compactStatus({ type: "retry", attempt: d.attempt, message: error.message, next: d.at, errorType: error.type, errorStatus: error.status })
  return { type: "session.status", data: { sessionID: d.sessionID, status } }
}

/** A ShellInfo or Pty (OpenCode) as a JobInfo. */
export function jobFromInfo(raw: unknown, kind: JobKind): (JobInfo & { sessionID?: string }) | undefined {
  const info = raw as Record<string, any> | null
  if (!info || typeof info !== "object" || typeof info.id !== "string" || !info.id) return undefined
  const status: JobStatus = JOB_STATUSES.has(info.status) ? info.status : "running"
  const commandLine = kind === "pty" ? [info.command, ...(Array.isArray(info.args) ? info.args : [])].filter((x) => typeof x === "string" && x).join(" ") || info.title : info.command
  const command = clipText(commandLine, JOB_COMMAND_MAX)
  const exit = finite(kind === "pty" ? info.exitCode : info.exit)
  const sessionID = typeof info.sessionID === "string" ? info.sessionID : typeof info.metadata?.sessionID === "string" ? info.metadata.sessionID : undefined
  const started = finite(info.time?.started)
  const ended = finite(info.time?.completed)
  return {
    ...(sessionID ? { sessionID } : {}),
    id: info.id,
    kind,
    ...(command ? { command } : {}),
    status,
    ...(exit !== undefined ? { exit } : {}),
    ...(info.metadata?.background === true ? { background: true as const } : {}),
    ...(started !== undefined ? { started } : {}),
    ...(ended !== undefined ? { ended } : {}),
  }
}

function compactJob(event: ForwardedEvent, sessionOf: ((jobID: string) => string | undefined) | undefined, now: number): ForwardedEvent | undefined {
  const d = event.data as Record<string, any>
  const type = event.type
  if (type === "session.status") {
    const status = compactStatus(d.status)
    return typeof d.sessionID === "string" && status ? { type, data: { sessionID: d.sessionID, status } } : undefined
  }
  const kind: JobKind = type.startsWith("pty.") ? "pty" : "shell"
  const session = (id: unknown, own?: unknown) => (typeof own === "string" && own ? own : typeof id === "string" ? sessionOf?.(id) : undefined)
  let data: Record<string, unknown> | undefined
  if (type === "shell.created" || type === "session.shell.started" || type === "pty.created" || type === "pty.updated") {
    const job = jobFromInfo(type === "session.shell.started" ? d.shell : d.info, kind)
    if (!job) return undefined
    const sessionID = session(job.id, type === "session.shell.started" ? d.sessionID : job.sessionID)
    const { started, ended: _ended, sessionID: _session, ...rest } = job
    data = sessionID ? { sessionID, ...rest, at: started ?? now } : undefined
  } else if (type === "session.shell.ended") {
    const job = jobFromInfo(d.shell, "shell")
    if (!job) return undefined
    const sessionID = session(job.id, d.sessionID)
    data = sessionID ? { sessionID, id: job.id, kind, status: job.status === "running" ? "exited" : job.status, ...(job.exit !== undefined ? { exit: job.exit } : {}), at: job.ended ?? now } : undefined
  } else if (type === "shell.exited" || type === "pty.exited") {
    const sessionID = session(d.id, d.sessionID)
    const exit = finite(kind === "pty" ? d.exitCode : d.exit)
    const status = kind === "pty" ? "exited" : JOB_STATUSES.has(d.status) && d.status !== "running" ? d.status : "exited"
    data = sessionID ? { sessionID, id: d.id, kind, status, ...(exit !== undefined ? { exit } : {}), at: now } : undefined
  } else {
    const sessionID = session(d.id, d.sessionID)
    data = sessionID && typeof d.id === "string" ? { sessionID, id: d.id, kind } : undefined
  }
  return data ? { type, data } : undefined
}
export * from "./work-source.ts"

// The node's only way to drive NVIDIA OpenShell (decision lk6gn3u7 §1): the `openshell` CLI, never a shell. Each call
// is spawn(binary, argv) with the global flags first (--gateway when configured, --workspace hub, --color never),
// `-o json` where the CLI has it, a time limit (the whole process group is killed) and cancellation. The first call
// checks `openshell --version` (0.1.x only: the CLI and its JSON change between minor versions). Errors are
// OpenShellErrors with a code and a short reason taken from the CLI's stderr, with the call's env values, the
// configured secrets and URL credentials removed: fit for the hub and a launch's reason.
//
// Names and labels are checked here, before anything runs, so nothing the hub sends can become a flag.
// node:child_process (not Bun.spawn) so the node also runs bundled for node.
import { spawn } from "node:child_process"
import path from "node:path"

/** The OpenShell workspace the hub's sandboxes live in. */
export const OPENSHELL_WORKSPACE = "hub"
/** The CLI versions this client speaks (`openshell --version`). */
export const SUPPORTED_VERSIONS = "0.1.x"
export const DEFAULT_TIMEOUT_MS = 60_000
/** Creating waits for the sandbox to come up (~20 s cold on the vm driver). */
export const CREATE_TIMEOUT_MS = 300_000
/** `sandbox exec` reads at most this much stdin. */
export const MAX_EXEC_STDIN = 4 * 1024 * 1024
/** The process limit beyond an exec's or a policy wait's own --timeout. */
const GRACE_MS = 30_000
const MAX_OUTPUT = 16 * 1024 * 1024
const REASON_MAX = 300
/** Inherited settings that would change what a call does; the client's flags decide instead. */
const DROPPED_ENV = new Set(["OPENSHELL_SANDBOX_POLICY", "OPENSHELL_WORKSPACE", "OPENSHELL_GATEWAY", "OPENSHELL_GATEWAY_ENDPOINT", "OPENSHELL_GATEWAY_INSECURE", "OPENSHELL_COLOR"])

const NAME = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?$/
const LABEL_KEY = /^([a-z0-9]([a-z0-9.-]{0,251}[a-z0-9])?\/)?[A-Za-z0-9]([A-Za-z0-9._-]{0,61}[A-Za-z0-9])?$/
const LABEL_VALUE = /^([A-Za-z0-9]([A-Za-z0-9._-]{0,61}[A-Za-z0-9])?)?$/
const ENV_NAME = /^[A-Za-z_][A-Za-z0-9_]*$/
const RESOURCE = /^[A-Za-z0-9][A-Za-z0-9._-]{0,62}$/

type Env = Readonly<Record<string, string | undefined>>

export type OpenShellErrorCode =
  | "not_installed"
  | "unsupported_version"
  | "invalid"
  | "not_found"
  | "already_exists"
  | "timeout"
  | "cancelled"
  | "bad_output"
  | "failed"

export class OpenShellError extends Error {
  override readonly name = "OpenShellError"
  constructor(
    message: string,
    readonly code: OpenShellErrorCode,
    readonly exitCode?: number,
  ) {
    super(message)
  }
}

export type SandboxPhase = "Provisioning" | "Ready" | "Error" | "Deleting" | "Stopping" | "Stopped" | "Starting" | "Completed" | "Unspecified" | "Unknown"

export interface SandboxCondition {
  readonly type: string
  readonly status: string
  readonly reason: string
  readonly message: string
}

/** A sandbox as `sandbox get/list/create -o json` reports it. */
export interface Sandbox {
  readonly id: string
  readonly name: string
  readonly workspace: string
  readonly phase: SandboxPhase
  readonly labels: Readonly<Record<string, string>>
  /** The main command's exit code once it ended, else null. */
  readonly exitCode: number | null
  readonly createdAt: string
  readonly conditions: readonly SandboxCondition[]
}

export interface GatewayStatus {
  readonly gateway: string
  readonly server: string
  readonly connected: boolean
  readonly authenticated: boolean
  readonly version: string
}

/** What `gateway info -o json` tells the node: the gateway's compute drivers (e.g. "vm"), its sandbox backends. */
export interface GatewayInfo {
  readonly computeDrivers: readonly string[]
}

export interface CreateSandboxOptions {
  readonly name: string
  /** A container image reference or rootfs tar (`--from`); or a template; or neither (the gateway's default image). */
  readonly from?: string
  readonly template?: string
  /** Policy YAML file (`--policy`). */
  readonly policyFile?: string
  /** Credential providers the node operator created (`--provider`). */
  readonly providers?: readonly string[]
  readonly labels?: Readonly<Record<string, string>>
  /** Non-secret environment (`--env`); secrets go through providers. */
  readonly env?: Readonly<Record<string, string>>
  /** The main command, started detached. */
  readonly command?: readonly string[]
}

export interface ExecOptions {
  readonly workdir?: string
  /** OpenShell's own limit (seconds); the process gets this plus a grace period. */
  readonly timeoutSec?: number
  readonly env?: Readonly<Record<string, string>>
  readonly stdin?: string | Uint8Array
}

export interface ExecResult {
  /** The remote command's exit code (openshell exits with it; a CLI failure also shows here, usually as 1). */
  readonly exitCode: number
  readonly stdout: string
  readonly stderr: string
}

export interface PolicySetOptions {
  /** Wait for the sandbox to load the policy. */
  readonly wait?: boolean
  readonly timeoutSec?: number
}

/** Per-call cancellation. */
export interface CallOptions {
  readonly signal?: AbortSignal
}

/** What the openshell runtime needs from OpenShell; OpenShellCli implements it over the CLI. */
export interface OpenShellClient {
  version(options?: CallOptions): Promise<string>
  status(options?: CallOptions): Promise<GatewayStatus>
  /** Optional: clients without it report no backends. */
  gatewayInfo?(options?: CallOptions): Promise<GatewayInfo>
  create(sandbox: CreateSandboxOptions, options?: CallOptions): Promise<Sandbox>
  /** undefined when there is no such sandbox. */
  get(name: string, options?: CallOptions): Promise<Sandbox | undefined>
  list(selector?: Readonly<Record<string, string>>, options?: CallOptions): Promise<Sandbox[]>
  exec(name: string, command: readonly string[], exec?: ExecOptions & CallOptions): Promise<ExecResult>
  upload(name: string, localPath: string, sandboxPath?: string, options?: CallOptions): Promise<void>
  download(name: string, sandboxPath: string, localPath: string, options?: CallOptions): Promise<void>
  stop(name: string, options?: CallOptions): Promise<void>
  /** Asks for deletion (OpenShell deletes asynchronously: poll get until undefined); a missing sandbox is fine. */
  delete(name: string, options?: CallOptions): Promise<void>
  policySet(name: string, policyFile: string, policy?: PolicySetOptions & CallOptions): Promise<void>
  /** Optional, read-only: the gateway's workspace names (`hub node openshell check`). */
  workspaces?(options?: CallOptions): Promise<string[]>
  /** Optional, read-only: the provider names in the client's workspace (`hub node openshell check`). */
  providers?(options?: CallOptions): Promise<string[]>
}

export interface OpenShellCliOptions {
  /** The executable (default "openshell" on PATH). */
  readonly binary?: string
  /** A gateway name (`--gateway`); default: the CLI's active gateway. */
  readonly gateway?: string
  /** Default OPENSHELL_WORKSPACE ("hub"). */
  readonly workspace?: string
  /** Limit per call (default 60 s); create gets CREATE_TIMEOUT_MS unless createTimeoutMs is set. */
  readonly timeoutMs?: number
  readonly createTimeoutMs?: number
  /** `sandbox list --page-size` (default 100). */
  readonly pageSize?: number
  /** The environment to start from (default process.env); OpenShell overrides are dropped from it. */
  readonly env?: Env
  /** Strings never to show in an error (tokens the caller knows about). */
  readonly secrets?: readonly string[]
}

interface RunOptions {
  readonly timeoutMs?: number
  readonly signal?: AbortSignal
  readonly stdin?: string | Uint8Array
  /** Extra strings to remove from errors (the call's env values). */
  readonly hide?: readonly string[]
  /** What the error names ("sandbox create"). */
  readonly what: string
}

interface RunResult {
  readonly exitCode: number
  readonly stdout: string
  readonly stderr: string
}

// ---- checks ----

function invalid(message: string): OpenShellError {
  return new OpenShellError(message, "invalid")
}

function checkName(name: string): void {
  if (!NAME.test(name)) throw invalid(`invalid sandbox name ${JSON.stringify(name)}: lowercase letters, digits and '-', at most 63`)
}

function checkLabels(labels: Readonly<Record<string, string>>): void {
  for (const [k, v] of Object.entries(labels)) {
    if (!LABEL_KEY.test(k)) throw invalid(`invalid label key ${JSON.stringify(k)}`)
    if (!LABEL_VALUE.test(v)) throw invalid(`invalid value for label ${k}: letters, digits, '.', '_' and '-', at most 63`)
  }
}

function checkResource(what: string, value: string): void {
  if (!RESOURCE.test(value)) throw invalid(`invalid ${what} ${JSON.stringify(value)}`)
}

/** A path argument that cannot be read as a flag. */
function checkPath(what: string, value: string): void {
  if (value === "" || value.startsWith("-") || value.includes("\0")) throw invalid(`invalid ${what} ${JSON.stringify(value)}`)
}

function envArgs(flag: string, env: Readonly<Record<string, string>> | undefined): string[] {
  const args: string[] = []
  for (const [k, v] of Object.entries(env ?? {})) {
    if (!ENV_NAME.test(k)) throw invalid(`invalid environment variable name ${JSON.stringify(k)}`)
    if (v.includes("\0")) throw invalid(`invalid value for ${k}`)
    args.push(flag, `${k}=${v}`)
  }
  return args
}

// ---- output ----

const ANSI = /\u001b\[[0-9;?]*[A-Za-z]/g

function escapeRegExp(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")
}

/** Removes the given strings, URL credentials and bearer tokens. */
export function redact(text: string, hide: readonly string[] = []): string {
  let out = text
  for (const s of [...hide].filter((s) => s.length >= 3).sort((a, b) => b.length - a.length)) out = out.replace(new RegExp(escapeRegExp(s), "g"), "***")
  return out.replace(/([a-z][a-z0-9+.-]*:\/\/)[^\s/@]+@/gi, "$1***@").replace(/(bearer\s+)[^\s"']+/gi, "$1***")
}

/** The gRPC message from a miette/tonic error, else the stderr's text, on one line. */
function reasonOf(stderr: string): string {
  const plain = stderr.replace(ANSI, "")
  const grpc = /message: "((?:[^"\\]|\\.)*)"/.exec(plain)
  const text = grpc ? grpc[1]! : plain
  return text
    .split("\n")
    .map((line) => line.replace(/^\s*(Error:)?\s*[×x]?\s*/, "").trim())
    .filter(Boolean)
    .join(" ")
}

function cut(text: string): string {
  return text.length > REASON_MAX ? `${text.slice(0, REASON_MAX)}…` : text
}

function parseJSON<T>(what: string, stdout: string): T {
  try {
    return JSON.parse(stdout) as T
  } catch {
    throw new OpenShellError(`openshell ${what}: output is not JSON`, "bad_output")
  }
}

const str = (v: unknown): string => (typeof v === "string" ? v : "")

function toSandbox(raw: unknown, what: string): Sandbox {
  if (!raw || typeof raw !== "object") throw new OpenShellError(`openshell ${what}: no sandbox in the output`, "bad_output")
  const o = raw as Record<string, unknown>
  if (typeof o.name !== "string" || typeof o.phase !== "string") throw new OpenShellError(`openshell ${what}: no sandbox in the output`, "bad_output")
  const labels: Record<string, string> = {}
  if (o.labels && typeof o.labels === "object") for (const [k, v] of Object.entries(o.labels)) if (typeof v === "string") labels[k] = v
  const conditions = Array.isArray(o.conditions)
    ? o.conditions.map((c: Record<string, unknown>) => ({ type: str(c?.type), status: str(c?.status), reason: str(c?.reason), message: str(c?.message) }))
    : []
  return {
    id: str(o.id),
    name: o.name,
    workspace: str(o.workspace),
    phase: o.phase as SandboxPhase,
    labels,
    exitCode: typeof o.exit_code === "number" ? o.exit_code : null,
    createdAt: str(o.created_at),
    conditions,
  }
}

// ---- the client ----

export class OpenShellCli implements OpenShellClient {
  readonly workspace: string
  private readonly binary: string
  private readonly timeoutMs: number
  private readonly createTimeoutMs: number
  private readonly pageSize: number
  private readonly env: Record<string, string>
  private readonly secrets: readonly string[]
  private readonly globals: readonly string[]
  private checked?: Promise<string>

  constructor(options: OpenShellCliOptions = {}) {
    this.binary = options.binary ?? "openshell"
    this.workspace = options.workspace ?? OPENSHELL_WORKSPACE
    this.timeoutMs = options.timeoutMs ?? DEFAULT_TIMEOUT_MS
    this.createTimeoutMs = options.createTimeoutMs ?? Math.max(CREATE_TIMEOUT_MS, this.timeoutMs)
    this.pageSize = options.pageSize ?? 100
    this.secrets = options.secrets ?? []
    if (options.gateway !== undefined) checkResource("gateway name", options.gateway)
    checkResource("workspace", this.workspace)
    this.globals = [...(options.gateway !== undefined ? ["--gateway", options.gateway] : []), "--workspace", this.workspace, "--color", "never"]
    const env: Record<string, string> = {}
    for (const [k, v] of Object.entries(options.env ?? process.env)) if (v !== undefined && !DROPPED_ENV.has(k)) env[k] = v
    env.NO_COLOR = "1"
    this.env = env
  }

  /** The CLI's version; rejects with unsupported_version outside 0.1.x. Checked once (a failure is retried). */
  version(options: CallOptions = {}): Promise<string> {
    this.checked ??= this.checkVersion(options).catch((error: unknown) => {
      this.checked = undefined
      throw error
    })
    return this.checked
  }

  async status(options: CallOptions = {}): Promise<GatewayStatus> {
    const { stdout } = await this.call(["status", "-o", "json"], { what: "status", ...options })
    const o = parseJSON<Record<string, unknown>>("status", stdout)
    const auth = (o.authentication ?? {}) as Record<string, unknown>
    return { gateway: str(o.gateway), server: str(o.server), connected: o.status === "connected", authenticated: auth.status === "authenticated", version: str(o.version) }
  }

  async gatewayInfo(options: CallOptions = {}): Promise<GatewayInfo> {
    const { stdout } = await this.call(["gateway", "info", "-o", "json"], { what: "gateway info", ...options })
    const o = parseJSON<{ compute_drivers?: unknown }>("gateway info", stdout)
    if (!Array.isArray(o.compute_drivers)) throw new OpenShellError("openshell gateway info: no compute drivers in the output", "bad_output")
    const computeDrivers = o.compute_drivers.map((d) => str((d as { name?: unknown } | null)?.name)).filter(Boolean)
    return { computeDrivers }
  }

  workspaces(options: CallOptions = {}): Promise<string[]> {
    return this.names(["workspace", "list"], "workspaces", options)
  }

  providers(options: CallOptions = {}): Promise<string[]> {
    return this.names(["provider", "list"], "providers", options)
  }

  async create(sandbox: CreateSandboxOptions, options: CallOptions = {}): Promise<Sandbox> {
    checkName(sandbox.name)
    const args = ["sandbox", "create", "--name", sandbox.name]
    if (sandbox.from !== undefined && sandbox.template !== undefined) throw invalid("give an image (from) or a template, not both")
    if (sandbox.from !== undefined) {
      checkPath("image", sandbox.from)
      args.push("--from", sandbox.from)
    }
    if (sandbox.template !== undefined) {
      checkResource("template", sandbox.template)
      args.push("--template", sandbox.template)
    }
    if (sandbox.policyFile !== undefined) {
      checkPath("policy file", sandbox.policyFile)
      args.push("--policy", sandbox.policyFile)
    }
    for (const p of sandbox.providers ?? []) {
      checkResource("provider", p)
      args.push("--provider", p)
    }
    checkLabels(sandbox.labels ?? {})
    for (const [k, v] of Object.entries(sandbox.labels ?? {})) args.push("--label", `${k}=${v}`)
    args.push(...envArgs("--env", sandbox.env), "--no-auto-providers", "--no-tty", "--detach", "-o", "json")
    if (sandbox.command?.length) args.push("--", ...sandbox.command)
    const { stdout } = await this.call(args, { what: "sandbox create", timeoutMs: this.createTimeoutMs, hide: Object.values(sandbox.env ?? {}), ...options })
    return toSandbox(parseJSON("sandbox create", stdout), "sandbox create")
  }

  async get(name: string, options: CallOptions = {}): Promise<Sandbox | undefined> {
    checkName(name)
    try {
      const { stdout } = await this.call(["sandbox", "get", name, "-o", "json"], { what: "sandbox get", ...options })
      return toSandbox(parseJSON("sandbox get", stdout), "sandbox get")
    } catch (error) {
      if (error instanceof OpenShellError && error.code === "not_found") return undefined
      throw error
    }
  }

  async list(selector: Readonly<Record<string, string>> = {}, options: CallOptions = {}): Promise<Sandbox[]> {
    checkLabels(selector)
    const select = Object.entries(selector).map(([k, v]) => `${k}=${v}`).join(",")
    const sandboxes: Sandbox[] = []
    let token = ""
    for (let page = 0; page < 10_000; page++) {
      const args = ["sandbox", "list", "--page-size", String(this.pageSize)]
      if (token) args.push("--page-token", token)
      if (select) args.push("--selector", select)
      args.push("-o", "json")
      const { stdout } = await this.call(args, { what: "sandbox list", ...options })
      const o = parseJSON<{ sandboxes?: unknown; next_page_token?: unknown }>("sandbox list", stdout)
      if (!Array.isArray(o.sandboxes)) throw new OpenShellError("openshell sandbox list: no sandboxes in the output", "bad_output")
      for (const s of o.sandboxes) sandboxes.push(toSandbox(s, "sandbox list"))
      token = str(o.next_page_token)
      if (!token) return sandboxes
    }
    throw new OpenShellError("openshell sandbox list: too many pages", "bad_output")
  }

  async exec(name: string, command: readonly string[], exec: ExecOptions & CallOptions = {}): Promise<ExecResult> {
    checkName(name)
    if (command.length === 0) throw invalid("exec needs a command")
    const stdinSize = typeof exec.stdin === "string" ? Buffer.byteLength(exec.stdin) : (exec.stdin?.byteLength ?? 0)
    if (stdinSize > MAX_EXEC_STDIN) throw invalid(`exec stdin is over ${MAX_EXEC_STDIN} bytes`)
    const args = ["sandbox", "exec", "--name", name, "--no-tty", "--no-login-shell"]
    if (exec.workdir !== undefined) {
      checkPath("workdir", exec.workdir)
      args.push("--workdir", exec.workdir)
    }
    const timeoutSec = exec.timeoutSec
    if (timeoutSec !== undefined) {
      if (!Number.isInteger(timeoutSec) || timeoutSec < 0) throw invalid("exec timeoutSec must be a whole number of seconds")
      args.push("--timeout", String(timeoutSec))
    }
    args.push(...envArgs("--env", exec.env), "--", ...command)
    const run: RunOptions = {
      what: "sandbox exec",
      timeoutMs: timeoutSec ? timeoutSec * 1000 + GRACE_MS : this.timeoutMs,
      hide: Object.values(exec.env ?? {}),
      ...(exec.signal ? { signal: exec.signal } : {}),
      ...(exec.stdin !== undefined ? { stdin: exec.stdin } : {}),
    }
    await this.version(exec)
    return this.run(args, run)
  }

  async upload(name: string, localPath: string, sandboxPath?: string, options: CallOptions = {}): Promise<void> {
    checkName(name)
    const local = path.resolve(localPath)
    const args = ["sandbox", "upload", "--no-git-ignore", name, local]
    if (sandboxPath !== undefined) {
      checkPath("sandbox path", sandboxPath)
      args.push(sandboxPath)
    }
    await this.call(args, { what: "sandbox upload", ...options })
  }

  async download(name: string, sandboxPath: string, localPath: string, options: CallOptions = {}): Promise<void> {
    checkName(name)
    checkPath("sandbox path", sandboxPath)
    await this.call(["sandbox", "download", name, sandboxPath, path.resolve(localPath)], { what: "sandbox download", ...options })
  }

  async stop(name: string, options: CallOptions = {}): Promise<void> {
    checkName(name)
    await this.call(["sandbox", "stop", name], { what: "sandbox stop", ...options })
  }

  async delete(name: string, options: CallOptions = {}): Promise<void> {
    checkName(name)
    await this.call(["sandbox", "delete", name], { what: "sandbox delete", ...options })
  }

  async policySet(name: string, policyFile: string, policy: PolicySetOptions & CallOptions = {}): Promise<void> {
    checkName(name)
    checkPath("policy file", policyFile)
    const args = ["policy", "set", "--policy", policyFile]
    let timeoutMs = this.timeoutMs
    if (policy.wait) {
      args.push("--wait")
      if (policy.timeoutSec !== undefined) {
        if (!Number.isInteger(policy.timeoutSec) || policy.timeoutSec <= 0) throw invalid("policy timeoutSec must be a positive whole number")
        args.push("--timeout", String(policy.timeoutSec))
      }
      timeoutMs = Math.max(timeoutMs, (policy.timeoutSec ?? 60) * 1000 + GRACE_MS)
    }
    args.push(name)
    await this.call(args, { what: "policy set", timeoutMs, ...(policy.signal ? { signal: policy.signal } : {}) })
  }

  /** The `name`s of a paged `<command> -o json` listing whose items sit under `field`. */
  private async names(command: readonly string[], field: string, options: CallOptions): Promise<string[]> {
    const what = command.join(" ")
    const names: string[] = []
    let token = ""
    for (let page = 0; page < 10_000; page++) {
      const args = [...command, "--page-size", String(this.pageSize)]
      if (token) args.push("--page-token", token)
      args.push("-o", "json")
      const { stdout } = await this.call(args, { what, ...options })
      const o = parseJSON<Record<string, unknown> | null>(what, stdout)
      const items = o && typeof o === "object" ? o[field] : undefined
      if (!Array.isArray(items)) throw new OpenShellError(`openshell ${what}: no ${field} in the output`, "bad_output")
      for (const item of items) {
        const name = str((item as { name?: unknown } | null)?.name)
        if (name) names.push(name)
      }
      token = str(o!.next_page_token)
      if (!token) return names
    }
    throw new OpenShellError(`openshell ${what}: too many pages`, "bad_output")
  }

  // ---- running ----

  private async checkVersion(options: CallOptions): Promise<string> {
    const { stdout } = await this.call(["--version"], { what: "--version", ...options }, false)
    const match = /(\d+)\.(\d+)\.(\d+)\S*/.exec(stdout)
    if (!match) throw new OpenShellError("openshell --version: no version in the output", "bad_output")
    if (match[1] !== "0" || match[2] !== "1") throw new OpenShellError(`openshell ${match[0]} is not supported (needs ${SUPPORTED_VERSIONS})`, "unsupported_version")
    return match[0]
  }

  /** Checks the version, runs, and turns a non-zero exit into an OpenShellError. */
  private async call(args: readonly string[], options: RunOptions, gate = true): Promise<RunResult> {
    if (gate) await this.version(options.signal ? { signal: options.signal } : {})
    const result = await this.run(args, options)
    if (result.exitCode !== 0) {
      const reason = reasonOf(result.stderr)
      const code: OpenShellErrorCode = /\bNotFound\b|\bnot found\b/i.test(reason + result.stderr) ? "not_found" : /\bAlreadyExists\b|already exists/i.test(reason + result.stderr) ? "already_exists" : "failed"
      const message = cut(redact(reason, [...this.secrets, ...(options.hide ?? [])])) || "no error output"
      throw new OpenShellError(`openshell ${options.what} failed (exit ${result.exitCode}): ${message}`, code, result.exitCode)
    }
    return result
  }

  private run(args: readonly string[], options: RunOptions): Promise<RunResult> {
    const what = `openshell ${options.what}`
    return new Promise((resolve, reject) => {
      if (options.signal?.aborted) return reject(new OpenShellError(`${what} cancelled`, "cancelled"))
      let settled = false
      const finish = (error: OpenShellError | undefined, result?: RunResult) => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        options.signal?.removeEventListener("abort", onAbort)
        if (error) reject(error)
        else resolve(result!)
      }
      // Its own process group, so a timeout or cancel also kills what openshell started.
      const child = spawn(this.binary, [...this.globals, ...args], { env: this.env, stdio: ["pipe", "pipe", "pipe"], detached: true, windowsHide: true })
      const kill = () => {
        try {
          if (child.pid) process.kill(-child.pid, "SIGKILL")
        } catch {
          child.kill("SIGKILL")
        }
      }
      const out: Buffer[] = []
      const err: Buffer[] = []
      let size = 0
      const collect = (into: Buffer[]) => (chunk: Buffer) => {
        size += chunk.length
        if (size > MAX_OUTPUT) {
          kill()
          return finish(new OpenShellError(`${what}: output over ${MAX_OUTPUT} bytes`, "bad_output"))
        }
        into.push(chunk)
      }
      child.stdout.on("data", collect(out))
      child.stderr.on("data", collect(err))
      child.stdin.on("error", () => {}) // the CLI may exit before reading stdin
      child.stdin.end(options.stdin === undefined ? undefined : Buffer.from(options.stdin))
      const timeoutMs = options.timeoutMs ?? this.timeoutMs
      const timer = setTimeout(() => {
        kill()
        finish(new OpenShellError(`${what} timed out after ${Math.round(timeoutMs / 1000)} s`, "timeout"))
      }, timeoutMs)
      const onAbort = () => {
        kill()
        finish(new OpenShellError(`${what} cancelled`, "cancelled"))
      }
      options.signal?.addEventListener("abort", onAbort, { once: true })
      child.on("error", (error: NodeJS.ErrnoException) => {
        if (error.code === "ENOENT") finish(new OpenShellError(`openshell is not installed (${this.binary} not found)`, "not_installed"))
        else finish(new OpenShellError(`${what} could not start: ${error.code ?? "error"}`, "failed"))
      })
      child.on("close", (code, signal) => {
        finish(undefined, { exitCode: code ?? (signal ? 128 : 1), stdout: Buffer.concat(out).toString("utf8"), stderr: Buffer.concat(err).toString("utf8") })
      })
    })
  }
}

// The `openshell` runtime of `hub node` (design §6.4): launches in NVIDIA OpenShell sandboxes. The CLI client
// (cli.ts), hub profiles (profiles.ts), the policy compiler (policy.ts) and the Runtime itself (runtime.ts).
export * from "./cli.ts"
export * from "./profiles.ts"
export * from "./policy.ts"
export * from "./runtime.ts"

// The Runtime interface (design §6.4): what `hub node` drives for each launch, prepare → (start) → collect →
// cleanup. A runtime keeps no state of its own between ops: prepare returns the Workspace and collect and cleanup
// get it back with the launch ID (a RunHandle; the hub stores it), so a restarted node can still collect and clean
// up what an earlier run prepared. A runtime must not trust a handle: it re-checks the workspace on every op.
//
// The `host` runtime has no start/stop: the session runs in the machine's long-running harness service, which the
// hub asks to create it. Sandbox runtimes (openshell) will implement start/stop.
import type {
  CleanupPolicy,
  LaunchArtifacts,
  LaunchRuntime,
  LaunchWorkspace,
  NodeRuntimeInfo,
  PreparedWorkspace,
} from "../../protocol/src/index.ts"

/** A prepared workspace: the session's directory and how it was made. */
export type Workspace = PreparedWorkspace
/** What collect found in a workspace (branch, head, commits since base, dirty). */
export type Artifacts = LaunchArtifacts

/** What prepare gets: the launch, its harness and runtime, and the workspace it asked for. */
export interface PrepareInput {
  readonly launchID: string
  readonly harness: string
  readonly runtime: LaunchRuntime
  readonly workspace: LaunchWorkspace
}

/** What start gets: the launch, its harness, how its spoke connects back to the hub, and extra environment. */
export interface StartInput {
  readonly launchID: string
  readonly harness: string
  /** The hub URL as the node knows it, and a token bound to this launch (secret: never in errors or argv). */
  readonly hub: { readonly url: string; readonly token: string }
  /** Extra non-secret environment for the harness (upper-case names). */
  readonly env?: Readonly<Record<string, string>>
}

/** Per-op context: cancellation, and a short human progress line ("cloning …"). */
export interface RuntimeContext {
  readonly signal?: AbortSignal
  readonly progress?: (message: string) => void
}

/** A launch's prepared (or started) workspace, as collect, cleanup and stop get it. */
export interface RunHandle {
  readonly launchID: string
  readonly workspace: Workspace
}

/** `removed: false` with a reason when the workspace was kept (policy keep, reused, uncommitted work). */
export interface CleanupResult {
  readonly removed: boolean
  readonly reason?: string
}

/** What start did: `started: false` with a reason when the harness had been started already (a repeated start). */
export interface StartResult extends RunHandle {
  readonly started: boolean
  readonly reason?: string
}

/** What stop did: `stopped: false` with a reason when nothing was running. */
export interface StopResult {
  readonly stopped: boolean
  readonly reason?: string
}

export type StopMode = "graceful" | "kill"

export interface Runtime {
  readonly kind: string
  /** What the node's hello reports for this runtime (kind, harnesses, profiles, backends). */
  info(): NodeRuntimeInfo
  prepare(input: PrepareInput, ctx?: RuntimeContext): Promise<Workspace>
  start?(workspace: Workspace, input: StartInput, ctx?: RuntimeContext): Promise<StartResult>
  stop?(handle: RunHandle, mode: StopMode): Promise<StopResult>
  collect(handle: RunHandle, ctx?: RuntimeContext): Promise<Artifacts>
  /** Keep, or remove without force: uncommitted or unpushed work, a reused workspace or another launch's keeps it. */
  cleanup(handle: RunHandle, policy: CleanupPolicy, ctx?: RuntimeContext): Promise<CleanupResult>
}

/** A runtime error with a message fit for the hub (and the launch's reason): no stack, no secrets. */
export class RuntimeError extends Error {
  override readonly name = "RuntimeError"
}

// The hub's backends (design §9): interfaces in ./types, in-memory implementations for the single-process hub,
// a file StateStore under <stateDir>/agent, and the cluster bundle (Postgres + Valkey). startCentral creates the bundle its config selects (hubBackends:
// file, or cluster when HUB_DATABASE_URL/HUB_VALKEY_URL are set) or takes one in its options, exposes it to
// new code only, and flushes its state on stop.
import { FileBlobStore } from "./file-blobs"
import { FileEventLog, removeJournal } from "./file-events"
import { FileStateStore, type FileStateStoreOptions } from "./file-state"
import { MemoryBlobStore } from "./memory-blobs"
import { MemoryBus } from "./memory-bus"
import { MemoryCatalog } from "./memory-catalog"
import { MemoryCounters, MemoryLocks } from "./memory-counters"
import { AGENT_EVENTS_AGE_MS, AGENT_EVENTS_MAX } from "../agent/events"
import { MemoryEventLog } from "./memory-events"
import { MemoryKv } from "./memory-kv"
import { MemoryStateStore } from "./memory-state"
import { randomUUID } from "node:crypto"
import { RedisClient } from "bun"
import { PostgresBlobStore } from "./postgres-blobs"
import { PostgresStateStore } from "./postgres-state"
import { ValkeyBus } from "./valkey-bus"
import { ValkeyCatalog } from "./valkey-catalog"
import { ValkeyCounters } from "./valkey-counters"
import { ValkeyEventLog } from "./valkey-events"
import { ValkeyKv } from "./valkey-kv"
import { ValkeyLocks } from "./valkey-locks"
import type { CentralConfig, ClusterConfig } from "../config"
import type { Backends, Clock, Timers } from "./types"

export * from "./types"

export interface MemoryBackendsOptions {
  /** The clock every backend reads (default Date.now). */
  readonly now?: Clock
  /** Timers for bus request timeouts (default real, unref'd timers). */
  readonly timers?: Timers
}

/** Every backend in process memory, on one clock. */
export function memoryBackends(options: MemoryBackendsOptions = {}): Backends {
  const now = options.now ?? Date.now
  return {
    state: new MemoryStateStore({ now }),
    bus: new MemoryBus(options.timers ? { timers: options.timers } : {}),
    events: new MemoryEventLog({ now }),
    agentEvents: new MemoryEventLog({ now, max: AGENT_EVENTS_MAX, maxAgeMs: AGENT_EVENTS_AGE_MS }),
    counters: new MemoryCounters({ now }),
    locks: new MemoryLocks({ now }),
    catalog: new MemoryCatalog({ now }),
    kv: new MemoryKv({ now }),
    blobs: new MemoryBlobStore({ now }),
  }
}


export interface FileBackendsOptions extends MemoryBackendsOptions, Pick<FileStateStoreOptions, "debounceMs" | "warn"> {
  /** The hub's state directory; the StateStore writes under <stateDir>/agent. */
  readonly stateDir: string
  /** (CE-4) The agent event journal in files under <stateDir>/agent/journal too (hub.json agents.durableJournal). */
  readonly durableJournal?: boolean
}

/**
 * The StateStore and artifact blobs in files under the state directory, every other backend in process memory, on one
 * clock. (CE-4) With `durableJournal`, the agent event journal is a FileEventLog there too, and close() writes it out
 * and marks it clean (the next start keeps its positions).
 */
export function fileBackends(options: FileBackendsOptions): Backends {
  const { stateDir, debounceMs, warn, durableJournal, ...memory } = options
  const state = new FileStateStore({
    stateDir,
    ...(memory.now ? { now: memory.now } : {}),
    ...(memory.timers ? { timers: memory.timers } : {}),
    ...(debounceMs !== undefined ? { debounceMs } : {}),
    ...(warn ? { warn } : {}),
  })
  const blobs = new FileBlobStore({ stateDir, ...(memory.now ? { now: memory.now } : {}) })
  if (!durableJournal) {
    // A journal left by a run with the setting on is stale from now on: never resumed by a later run with it on.
    removeJournal(stateDir)
    return { ...memoryBackends(memory), state, blobs }
  }
  const journal = new FileEventLog({ stateDir, max: AGENT_EVENTS_MAX, maxAgeMs: AGENT_EVENTS_AGE_MS, ...(memory.now ? { now: memory.now } : {}), ...(memory.timers ? { timers: memory.timers } : {}), ...(warn ? { warn } : {}) })
  return { ...memoryBackends(memory), state, blobs, agentEvents: journal, close: () => journal.close() }
}

export interface ClusterBackendsOptions extends MemoryBackendsOptions {
  /** HUB_DATABASE_URL / HUB_VALKEY_URL and the pod id (see ../config). */
  readonly cluster: ClusterConfig
  /** Opens the Valkey client kv, counters, locks, events and catalog share (default: Bun.RedisClient; tests). */
  readonly valkeyClient?: (url: string) => RedisClient
}

/**
 * State in Postgres, everything else in Valkey (design §9). Built synchronously, nothing connects until first
 * use: the Postgres pool checks the schema then (it never migrates: `hub-server migrate` does), and one Valkey
 * client, opened on the first command, serves kv, counters, locks, events and catalog; the bus opens its own
 * (pub/sub needs dedicated connections). close() closes them all. URLs are never put in a message.
 */
export function clusterBackends(options: ClusterBackendsOptions): Backends {
  const { cluster } = options
  const now = options.now
  const open = options.valkeyClient ?? ((url: string) => new RedisClient(url))
  let client: RedisClient | undefined
  // One lazily opened client behind the shape the Valkey backends use (send / close).
  const shared = {
    send: (command: string, args: string[]) => (client ??= open(cluster.valkeyURL)).send(command, args),
    close: () => {
      client?.close()
      client = undefined
    },
  } as unknown as RedisClient
  const timeout = cluster.statementTimeoutMs !== undefined ? { statementTimeoutMs: cluster.statementTimeoutMs } : {}
  const state = new PostgresStateStore({ url: cluster.databaseURL, ...timeout, ...(now ? { now } : {}) })
  // Artifact bytes in the same database (HWA-22, decision tctkrik8), on their own small pool.
  const blobs = new PostgresBlobStore({ url: cluster.databaseURL, ...timeout, ...(now ? { now } : {}) })
  const bus = new ValkeyBus(cluster.valkeyURL, { instanceID: `${cluster.podID}-${randomUUID().slice(0, 8)}`, ...(options.timers ? { timers: options.timers } : {}) })
  return {
    state,
    bus,
    events: new ValkeyEventLog(shared, now ? { now } : {}),
    agentEvents: new ValkeyEventLog(shared, { ...(now ? { now } : {}), max: AGENT_EVENTS_MAX, maxAgeMs: AGENT_EVENTS_AGE_MS, prefix: "hub:agent:" }),
    counters: new ValkeyCounters(shared),
    locks: new ValkeyLocks(shared, now ? { now } : {}),
    catalog: new ValkeyCatalog(shared, now ? { now } : {}),
    kv: new ValkeyKv(shared),
    blobs,
    async close() {
      bus.close()
      shared.close()
      await state.close()
      await blobs.close()
    },
  }
}

/** The hub's bundle for its config: the cluster one when cluster mode is configured, else the file one. */
export function hubBackends(config: Pick<CentralConfig, "stateDir" | "cluster" | "durableJournal">, options: MemoryBackendsOptions = {}): Backends {
  return config.cluster ? clusterBackends({ ...options, cluster: config.cluster }) : fileBackends({ ...options, stateDir: config.stateDir, ...(config.durableJournal ? { durableJournal: true } : {}) })
}

// CON-04 the Concierge's module slots (contract "Parallel safety of CON-05/06/07"). The service wires these ports;
// CON-05 (notifier.ts) and CON-06 (tiers.ts) each fill one slot line in CONCIERGE_SLOTS and touch nothing else here.
// Every slot defaults to a no-op, so the hub runs the same without them.
import type { ConciergeSettings, ConciergeStatus } from "../../../packages/protocol/src/concierge"
import type { UserActor } from "../agent/actor"
import type { ActOutcome, Decision } from "../agent/decisions"
import type { AgentEvent } from "../agent/events"
import type { AgentRoute } from "../agent/routes"
import type { ConciergeEntitlements } from "./entitlements"
import { ConciergeNotifierImpl, type NotifierJournal } from "./notifier"
import { conciergeTiers, type TierPorts } from "./tiers"
import type { ConciergeIdentity } from "./watchlist-routes"

/** What the Concierge modules get from the hub. */
export interface ConciergePorts {
  /** The user's current Concierge session and every hidden one (the Concierge-only authority). */
  readonly identity: ConciergeIdentity
  readonly status: (userID: string) => Promise<ConciergeStatus>
  readonly settings: (userID: string) => Promise<ConciergeSettings>
  /** Pushes the board context to the current session, awaited at most 2 s (before a wake). False: not there. */
  readonly beforeWake: (userID: string) => Promise<boolean>
  /**
   * Sends a message to the user's current Concierge session as app:concierge (Delivery.send; the inbound rule admits
   * it). Throws not_found when there is no current session.
   */
  readonly send: (userID: string, text: string, options: { readonly wake: boolean; readonly urgent?: boolean; readonly batch?: { readonly id: string; readonly kind: string; readonly budget?: string; readonly lines: number } }) => Promise<{ readonly messageID: string; readonly woke?: boolean }>
  readonly entitlements: ConciergeEntitlements
  /** Every user of the hub (leader loops). */
  readonly users: () => Promise<Iterable<string>>
  /** (CON-05) The notifier's journal, ledger store, watchlist view, board revision and leadership; absent: inert. */
  readonly journal?: NotifierJournal
  /** (CON-06) What the tiers slot needs from the hub (Decisions, acting, presence, devices, SSE). */
  readonly tiers?: TierPorts
}

/** CON-05: event-driven turns, digests, quiet hours (runs on the `concierge` leader). */
export interface ConciergeNotifier {
  /** The concierge leader was elected (start) or deposed (stop). */
  start(): void
  stop(): void
  /** Every journal append of the user, on the appending pod. Must never throw (never awaited). */
  observe(userID: string, event: AgentEvent): void
  /** The Concierge was disabled: forget the user's ledger. Must never reject. */
  disabled(userID: string): Promise<void>
}

/** CON-06: approval tiers, proposals and arming (its Concierge-only routes). */
export interface ConciergeTiers {
  routes(): AgentRoute[]
  /** Runs a proposal Decision's `act` action when the user answers (absent: it cannot run on this hub). */
  act?(userID: string, decision: Decision, choice: { readonly option?: string }, by: UserActor): Promise<ActOutcome>
  /** Admits a voice/text answer (throws forbidden "Answer this decision with a tap"); absent: never admitted. */
  checkVia?(userID: string, decision: Decision, via: "voice" | "text", by: UserActor): Promise<void>
  /** A Decision changed (Decisions' changed listener): an answered/closed one is disarmed. Never throws. */
  decisionChanged?(userID: string, decision: Decision): void
  /** The Decision armed now by the current Concierge session, if any (the board's `armed` flag). */
  armedID?(userID: string): Promise<string | undefined>
  /** The hub is stopping: drop timers. */
  stop?(): void
}

export const NO_NOTIFIER: ConciergeNotifier = { start: () => undefined, stop: () => undefined, observe: () => undefined, disabled: async () => undefined }
export const NO_TIERS: ConciergeTiers = { routes: () => [] }

export interface ConciergeSlots {
  readonly notifier?: (ports: ConciergePorts) => ConciergeNotifier
  readonly tiers?: (ports: ConciergePorts) => ConciergeTiers
}

/** The filled slots (one line each). */
export const CONCIERGE_SLOTS: ConciergeSlots = {
  notifier: (ports) => new ConciergeNotifierImpl(ports), // CON-05
  tiers: (ports) => conciergeTiers(ports), // CON-06
}

export interface ConciergeModules {
  readonly notifier: ConciergeNotifier
  readonly tiers: ConciergeTiers
}

/** The modules for these ports: each slot's own, else its no-op. */
export function conciergeModules(ports: ConciergePorts, slots: ConciergeSlots = CONCIERGE_SLOTS): ConciergeModules {
  return { notifier: slots.notifier?.(ports) ?? NO_NOTIFIER, tiers: slots.tiers?.(ports) ?? NO_TIERS }
}

