    this.devLimits = { ...DEV_LIMITS, ...options.devLimits }
    // Unique per process: a restarted pod never reuses another's page keys.
    this.podTag = `${(options.podID ?? "hub").replace(/[^A-Za-z0-9]/g, "").slice(0, 12) || "hub"}${randomBytes(3).toString("hex")}`
    this.store = new RecordingStore(options.state, options.blobs, this.now)
    this.settings = new RecordingSettingsStore(options.state, this.now)
    this.writer = new HubEventWriter({
      store: this.store,
      now: this.now,
      podTag: this.podTag,
      ...(options.hubFlushMs !== undefined ? { flushMs: options.hubFlushMs } : {}),
      failed: (cause) => this.log(`[hub] recording hub events not written: ${(cause as Error).message}`),
      overLimit: (userID, id, scope) =>
        void (async () => {
          const record = await this.store.visible(userID, id)
          if (record) await this.capReached(userID, record, "events", scope, scope === "user" ? PAGE_QUOTA_BYTES : L.eventsPerRecording)
          await this.endByHub(userID, id, "limit")
        })().catch(() => undefined),
    })
    this.retention = new RecordingRetention({ users: options.users, sweepUser: (userID) => this.sweepUser(userID), ...(options.sweepMs !== undefined ? { sweepMs: options.sweepMs } : {}), log: (m) => this.log(m) })
    this.registryTap = new RegistryTaps(
      {
        hub: (userID, sessionID, kind, fields) => this.hub(userID, sessionID, kind, fields),
        mayRecord: (userID) => this.mayRecord(userID),
        turnDetail: (userID, sessionID, detail) => void this.track(this.turnDetail(userID, sessionID, detail)).catch((cause) => this.log(`[hub] recording turn detail failed: ${(cause as Error).message}`)),
      },
      this.now,
    )
    if (options.bus) {
      options.bus
        .subscribe(RECORDINGS_TOPIC, (message) => {
          const userID = (message as { userID?: unknown } | undefined)?.userID
          if (typeof userID === "string") this.active.delete(userID)
        })
        .then((off) => (this.unsubscribe = off))
        .catch((cause) => this.log(`[hub] recordings bus subscription failed: ${(cause as Error).message}`))
    }
  }

  private log(message: string): void {
    ;(this.options.log ?? console.error)(message)
  }

  /** Tracks a background promise (settled() waits for them). */
  private track<T>(promise: Promise<T>): Promise<T> {
    this.background.add(promise)
    void promise.finally(() => this.background.delete(promise)).catch(() => undefined)
    return promise
  }

  // ---- the active index ------------------------------------------------------------------------------------

  /** The user's active recordings (per pod, refreshed by the bus and after ACTIVE_TTL_MS). */
  private async activeOf(userID: string): Promise<ActiveRef[]> {
    const cached = this.active.get(userID)
    if (cached && this.now() - cached.at < ACTIVE_TTL_MS) return cached.refs
    const refs = (await this.store.list(userID)).filter((r) => r.state === "active").map((r) => ({ id: r.id, sessionID: r.sessionID, kind: r.kind, deviceID: r.deviceID, ...(r.developer ? { developer: true as const } : {}) }))
    this.active.set(userID, { at: this.now(), refs })
    if (this.active.size > 10_000) this.active.delete(this.active.keys().next().value as string)
    return refs
  }

  /** False only when the user surely has no active recording. */
  mayRecord(userID: string): boolean {
    const cached = this.active.get(userID)
    return !(cached && this.now() - cached.at < ACTIVE_TTL_MS && cached.refs.length === 0)
  }

  /** A recording of the user started or ended: this pod's index and every other pod's are refreshed. */
  private changed(userID: string, sessionID: string): void {
    this.active.delete(userID)
    void this.options.bus?.publish(RECORDINGS_TOPIC, { userID, sessionID }).catch(() => undefined)
  }

  // ---- hub events ------------------------------------------------------------------------------------------

  /** Records a hub event into every active recording of (user, session), in call order per user. */
  hub(userID: string, sessionID: string, kind: HubEventKind, fields: Record<string, unknown>, only?: RecordingKind): void {
    void this.hubNow(userID, sessionID, kind, fields, only)
  }

  /** hub(), resolving once the event is buffered. */
  hubNow(userID: string, sessionID: string, kind: HubEventKind, fields: Record<string, unknown>, only?: RecordingKind): Promise<void> {
    const at = this.now()
    const add = (refs: readonly ActiveRef[]) => {
      for (const ref of refs) if (ref.sessionID === sessionID && (only === undefined || ref.kind === only)) this.writer.add(userID, ref.id, kind, fields, at)
    }
    const cached = this.active.get(userID)
    if (!this.tails.has(userID) && cached && this.now() - cached.at < ACTIVE_TTL_MS) {
      add(cached.refs)
      return Promise.resolve()
    }
    const run = (this.tails.get(userID) ?? Promise.resolve())
      .then(async () => add(await this.activeOf(userID)))
      .catch((cause) => this.log(`[hub] recording tap failed: ${(cause as Error).message}`))
    this.tails.set(userID, run)
    void run.finally(() => {
      if (this.tails.get(userID) === run) this.tails.delete(userID)
    })
    return run
  }

  /**
   * (Developer mode) turn.detail into the session's active developer recordings: the turn's timings and what ran it
   * (asked of the session only then, at most TURN_FACTS_MS). Only the whitelisted facts: never text.
   */
  private async turnDetail(userID: string, sessionID: string, detail: TurnTimings): Promise<void> {
    if (!this.mayRecord(userID)) return
    const refs = (await this.activeOf(userID)).filter((r) => r.sessionID === sessionID && r.developer)
    if (!refs.length) return
    let facts: TurnFacts = {}
    if (this.options.turnFacts) {
      const timeout = new Promise<TurnFacts>((resolve) => setTimeout(() => resolve({}), TURN_FACTS_MS).unref?.())
      facts = await Promise.race([this.options.turnFacts(userID, sessionID).catch(() => ({})), timeout])
    }
    const at = this.now()
    const label = (v: unknown) => (typeof v === "string" && v ? v.slice(0, 120) : undefined)
    const count = (v: unknown) => (typeof v === "number" && Number.isFinite(v) && v >= 0 ? Math.round(v) : undefined)
    const picked = Object.fromEntries(
      Object.entries({ provider: label(facts.provider), model: label(facts.model), variant: label(facts.variant), agent: label(facts.agent), contextTokens: count(facts.contextTokens), contextLimit: count(facts.contextLimit) }).filter(([, v]) => v !== undefined),
    )
    const tools = detail.tools.map((t) => ({ callID: t.callID.slice(0, 120), ...(t.tool ? { tool: t.tool } : {}), startMs: t.startMs, ...(t.endMs !== undefined ? { endMs: t.endMs } : {}), state: t.state }))
    for (const ref of refs) this.writer.add(userID, ref.id, "turn.detail", { outcome: detail.outcome, ms: detail.ms, ...(detail.firstTokenMs !== undefined ? { firstTokenMs: detail.firstTokenMs } : {}), ...picked, tools }, at)
  }

  /** Writes every buffered hub event now. */
  async flush(): Promise<void> {
    await Promise.all([...this.tails.values()])
    await this.writer.flush()
  }

  /** Waits for background work (large audio writes, delete-all) and flushes. */
  async settled(): Promise<void> {
    while (this.background.size) await Promise.allSettled([...this.background])
    await this.flush()
  }

  async stop(): Promise<void> {
    this.retention.stop()
    await this.settled().catch(() => undefined)
    await this.unsubscribe?.().catch(() => undefined)
  }

