  // ---- appends ---------------------------------------------------------------------------------------------

  /** The recording when this device may append to it now: active, or ended within its grace. */
  async appendable(userID: string, deviceID: string, id: string): Promise<{ kind: "ok"; record: RecordingRecord } | { kind: "not_found" } | { kind: "ended"; reason: RecordingEndReason }> {
    const record = await this.store.visible(userID, id)
    if (!record || record.deviceID !== deviceID) return { kind: "not_found" }
    const now = this.now()
    if (record.state === "active" && now - record.startedAt >= L.maxDurationMs) {
      const after = await this.end(userID, id, "max_duration")
      return { kind: "ended", reason: after?.endReason ?? "max_duration" }
    }
    if (record.state === "active") return { kind: "ok", record }
    if (record.graceUntil !== undefined && now <= record.graceUntil) return { kind: "ok", record }
    return { kind: "ended", reason: record.endReason ?? "stopped" }
  }

  async appendConsole(userID: string, record: RecordingRecord, events: Parameters<typeof ingestConsole>[3]): Promise<{ kind: "ok"; through: number; audio: boolean } | { kind: "limit" } | { kind: "not_found" }> {
    const ingested = await ingestConsole(this.store, userID, record, events, this.now)
    if (ingested.kind === "gone") return { kind: "not_found" }
    if (ingested.kind === "limit" || ingested.kind === "quota") {
      if (ingested.kind === "quota") await this.capReached(userID, record, "events", "user", PAGE_QUOTA_BYTES)
      else await this.capReached(userID, record, "events", "recording", L.eventsPerRecording)
      await this.end(userID, record.id, "limit")
      return { kind: "limit" }
    }
    return { kind: "ok", through: ingested.record.consoleThrough, audio: ingested.record.audio }
  }

  /** cap.reached once per (what, scope); an audio cap also turns the recording's audio off (SSE audio:false). */
  private async capReached(userID: string, record: RecordingRecord, what: "audio" | "events", scope: "user" | "recording", limit: number): Promise<void> {
    const key = `${what}:${scope}`
    let note = false
    let audioOff = false
    const result = await this.store.update(userID, record.id, (current) => {
      note = !current.capNoted.includes(key)
      audioOff = what === "audio" && current.audio
      if (!note && !audioOff) return undefined
      return { ...current, capNoted: note ? [...current.capNoted, key] : current.capNoted, ...(what === "audio" ? { audio: false } : {}) }
    })
    if (!result?.changed) return
    if (note) this.writer.add(userID, record.id, "cap.reached", { what, scope, limit })
    if (audioOff) this.options.notify(userID, { type: "recording", recordingID: record.id, audio: false })
  }

  /** The user cap for a new segment of `bytes` (cap.reached / audio off when hit); the blob quota enforces it atomically. */
  private async audioAllowed(userID: string, record: RecordingRecord, bytes: number): Promise<boolean> {
    if (bytes > L.segmentBytes) return false
    if (!record.audio) return false
    if ((await this.store.usage(userID)) + bytes > L.userBytes) {
      await this.capReached(userID, record, "audio", "user", L.userBytes)
      return false
    }
    return true
  }

  /**
   * Reserves a segment's bytes and count in the record (CAS), so parallel writes never pass recordingBytes or
   * segmentsPerRecording: "ok", "cap" (cap.reached, audio off), or "gone" (deleted meanwhile).
   */
  private async reserveAudio(userID: string, record: RecordingRecord, bytes: number): Promise<"ok" | "cap" | "gone"> {
    let verdict = "gone" as "ok" | "cap" | "over" | "gone"
    const at = this.now()
    await this.store.update(userID, record.id, (current) => {
      if (current.state === "deleting") return void (verdict = "gone")
      if (!current.audio) return void (verdict = "cap")
      if (current.segments >= L.segmentsPerRecording || current.bytes + bytes > L.recordingBytes) return void (verdict = "over")
      verdict = "ok"
      return { ...current, segments: current.segments + 1, bytes: current.bytes + bytes, lastEventAt: at }
    })
    if (verdict === "over") {
      await this.capReached(userID, record, "audio", "recording", L.recordingBytes)
      return "cap"
    }
    return verdict
  }

  /** Gives a reservation back (the write failed or lost the first-write race). */
  private async releaseAudio(userID: string, id: string, bytes: number): Promise<void> {
    await this.store.update(userID, id, (current) => (current.state === "deleting" ? undefined : { ...current, segments: Math.max(0, current.segments - 1), bytes: Math.max(0, current.bytes - bytes) }))
  }

  /** Stores a segment's WAV (first write wins); the caps are checked (and reserved) first. */
  async storeAudio(userID: string, record: RecordingRecord, n: number, audio: Uint8Array, via: AudioEntry["via"], redacted = false): Promise<AudioOutcome> {
    const existing = await this.store.indexEntry<AudioEntry>(userID, record.id, audioKey(n))
    if (existing) return { kind: "stored", entry: existing, fresh: false }
    if (!(await this.audioAllowed(userID, record, audio.length))) return { kind: "cap" }
    const reserved = await this.reserveAudio(userID, record, audio.length)
    if (reserved === "cap") return { kind: "cap" }
    if (reserved === "gone") return { kind: "gone" }
    let ref
    try {
      ref = await this.store.putBlob(userID, audio, RECORDING_AUDIO_TYPE, L.segmentBytes, L.userBytes)
    } catch (cause) {
      await this.releaseAudio(userID, record.id, audio.length)
      if (cause instanceof BlobQuotaError) {
        await this.capReached(userID, record, "audio", "user", L.userBytes)
        return { kind: "cap" }
      }
      return { kind: "failed", cause }
    }
    const at = this.now()
    const entry: AudioEntry = { hash: ref.hash, bytes: ref.bytes, at, via, ...(redacted ? { redacted: true as const } : {}) }
    if (!(await this.store.putIndex(userID, record.id, audioKey(n), entry))) {
      await this.releaseAudio(userID, record.id, audio.length)
      const first = await this.store.indexEntry<AudioEntry>(userID, record.id, audioKey(n))
      if (first?.hash !== ref.hash) await this.store.dropIfUnindexed(userID, ref.hash, at)
      return first ? { kind: "stored", entry: first, fresh: false } : { kind: "failed", cause: new Error("segment index lost") }
    }
    // A deletion that ran meanwhile did not see this segment: undo it (delete is real).
    if (await this.store.undoIfDeleted(userID, record.id, audioKey(n), ref.hash)) return { kind: "gone" }
    return { kind: "stored", entry, fresh: true }
  }

