  /** POST …/conversation: the event, and (off) the session's recordings end with a grace for the last batches. */
  async conversationChanged(userID: string, sessionID: string, on: boolean): Promise<void> {
    await this.hubNow(userID, sessionID, "conversation", { on })
    if (on) return
    for (const ref of await this.activeOf(userID)) {
