  }

  /** A session was deleted: its recordings end. */
  async sessionDeleted(userID: string, sessionID: string): Promise<void> {
    for (const ref of await this.activeOf(userID)) if (ref.sessionID === sessionID) await this.end(userID, ref.id, "session_deleted")
  }

  /** Decisions: opened (asked by the recorded session) and answered (with via). */
  decisionChanged(userID: string, decision: Decision): void {
    const from = decision.from
    if (from.kind !== "session") return
    const sessionID = from.sessionID
    if (decision.state === "open" && !this.opened.has(decision.id)) {
      this.opened.add(decision.id)
      if (this.opened.size > 2000) this.opened.delete(this.opened.values().next().value as string)
      this.hub(userID, sessionID, "decision.opened", { decisionID: decision.id, from: partyKey(from), tier: decision.tier, urgency: decision.urgency, options: decision.options.map((o) => o.id), text: decision.question })
    } else if (decision.state === "answered" && decision.answer?.answeredBy === "user") {
      const picks = decision.answer.picks && Object.entries(decision.answer.picks).map(([group, option]) => ({ group, option }))
      this.hub(userID, sessionID, "decision.answered", { decisionID: decision.id, ...(decision.answer.option !== undefined ? { option: decision.answer.option } : {}), ...(picks ? { picks } : {}), via: decision.answer.via ?? "tap" })
    }
  }

  /** concierge.tool: an agent call of a recorded Concierge session (no body, no response). */
  conciergeCall(userID: string, sessionID: string, fields: ConciergeCallFields): void {
    if (!this.mayRecord(userID)) return
    this.hub(userID, sessionID, "concierge.tool", { ...fields }, "concierge")
  }

  /** wake.arrived: the notifier's send to the recorded Concierge session succeeded. */
  wake(userID: string, sessionID: string, fields: Record<string, unknown>): void {
    this.hub(userID, sessionID, "wake.arrived", fields, "concierge")
  }

  // ---- reads -----------------------------------------------------------------------------------------------

  async visible(userID: string, id: string): Promise<RecordingRecord | undefined> {
    return this.store.visible(userID, id)
  }

  async list(userID: string): Promise<RecordingRecord[]> {
    return (await this.store.list(userID)).filter((r) => r.state !== "deleting").sort((a, b) => b.startedAt - a.startedAt || (a.id < b.id ? 1 : -1))
  }

  /** One export slot of the user, or undefined at EXPORTS_PER_USER; release it when the stream ends. */
  exportSlot(userID: string): (() => void) | undefined {
    const running = this.exports.get(userID) ?? 0
    if (running >= EXPORTS_PER_USER) return undefined
    this.exports.set(userID, running + 1)
    let released = false
    return () => {
      if (released) return
      released = true
      const left = (this.exports.get(userID) ?? 1) - 1
      if (left <= 0) this.exports.delete(userID)
      else this.exports.set(userID, left)
    }
  }

  // ---- delete ----------------------------------------------------------------------------------------------

  /** Step 1: ends an active recording (stopped), then marks it deleting (invisible to every route from then on). */
  private async markDeleting(userID: string, id: string): Promise<boolean> {
    const record = await this.store.visible(userID, id)
    if (!record) return false
    if (record.state === "active") await this.end(userID, id, "stopped")
    await this.writer.flush(userID, id)
    const at = this.now()
    await this.store.tombstone(userID, id, at)
    const result = await this.store.update(userID, id, (current) => (current.state === "deleting" ? undefined : { ...current, state: "deleting", deletingAt: at }))
    if (!result?.changed) return false
    this.writer.discard(userID, id)
    this.options.notify(userID, { type: "recording", recordingID: id, state: "deleted" })
    return true
  }

  async deleteOne(userID: string, id: string): Promise<boolean> {
    if (!(await this.markDeleting(userID, id))) return false
    await this.store.finishDelete(userID, id)
    await this.options.audit({ actor: userID, action: "recording.delete", target: id, detail: "1" })
    return true
  }

  /** Every recording of the user: marked now, finished in the background (the sweep finishes what a crash left). */
  async deleteAll(userID: string): Promise<number> {
    const ids: string[] = []
    for (const record of await this.store.list(userID)) if (record.state !== "deleting" && (await this.markDeleting(userID, record.id))) ids.push(record.id)
    await this.options.audit({ actor: userID, action: "recording.delete", target: "all", detail: String(ids.length) })
    void this.track(
      (async () => {
        for (const id of ids) await this.store.finishDelete(userID, id).catch((cause) => this.log(`[hub] recording delete not finished: ${(cause as Error).message}`))
      })(),
    )
    return ids.length
  }

  // ---- retention -------------------------------------------------------------------------------------------

  /** One user's sweep: finish deletions, delete expired, end idle and over-long active recordings. */
  async sweepUser(userID: string): Promise<number> {
    const now = this.now()
    let expired = 0
    for (const record of await this.store.list(userID)) {
      if (record.state === "deleting") {
        await this.store.finishDelete(userID, record.id)
        continue
      }
      if (record.expiresAt <= now) {
        if (record.state === "active") await this.end(userID, record.id, "stale")
        if (await this.markDeleting(userID, record.id)) {
          await this.store.finishDelete(userID, record.id)
          expired++
        }
        continue
      }
      if (record.state !== "active") continue
      if (now - record.startedAt >= L.maxDurationMs) await this.end(userID, record.id, "max_duration")
      else if (now - record.lastEventAt >= L.idleEndMs && !this.options.conversation(record.sessionID)) await this.end(userID, record.id, "stale")
    }
    // Leftovers of writes that raced a deletion (index keys of gone recordings, unindexed blobs past the grace).
    await this.store.sweepOrphans(userID)
    if (expired) await this.options.audit({ actor: "system", action: "recording.purge", detail: `${expired} expired` })
    return expired
  }
}

export interface StartInput {
  readonly sessionID: string
  readonly clientID: string
  readonly anchor?: RecordingRecord["anchor"]
  readonly client?: RecordingRecord["client"]
}

export type StartResult =
  | { readonly kind: "off" | "not_found" | "rate_limited" | "limit" }
  | { readonly kind: "existing" | "created"; readonly record: RecordingRecord }

export { summaryOf }

const concat = (chunks: readonly Uint8Array[]): Uint8Array => {
  const out = new Uint8Array(chunks.reduce((n, c) => n + c.length, 0))
  let at = 0
  for (const c of chunks) {
    out.set(c, at)
    at += c.length
  }
  return out
}

/** stt.result's provider fields (capture.v2): the upstream HTTP status, response bytes and time to headers, when known. */
function providerStats(stats: TranscribeStats | undefined): Record<string, number> {
  const out: Record<string, number> = {}
  const finite = (x: unknown): x is number => typeof x === "number" && Number.isFinite(x)
  if (finite(stats?.status)) out.httpStatus = stats.status
  if (finite(stats?.bytes)) out.responseBytes = stats.bytes
  if (finite(stats?.headersMs)) out.headersMs = Math.round(stats.headersMs)
  return out
}

