/** The environment variable holding the release signing key (a GitHub Actions secret; decision Q5). */
export const SIGNING_KEY_ENV = "HUB_RELEASE_SIGNING_KEY"
/** The trust root the release binaries embed, relative to the repository root (checked in once the key exists). */
export const TRUST_ROOT_FILE = "packages/cli/src/bootstrap/release/trust-root.json"
/** The program compiled into hubctl (I3). */
export const HUBCTL_ENTRY = "packages/cli/src/main.ts"
export const DEFAULT_KEY_ID = "hub-release-1"
/** The version hubctl --version prints, and the release the manifest names. */
export const HUBCTL_VERSION: string = pkg.version

export interface ReleaseIo {
  readonly env: Readonly<Record<string, string | undefined>>
  /** The repository root; relative paths resolve against it. */
  readonly cwd: string
  readonly stdout: (s: string) => void
  readonly stderr: (s: string) => void
  /** Runs a word list (no shell) in `cwd`; resolves to its exit code. */
  readonly run: (argv: string[]) => Promise<number>
  readonly download: Downloader
  readonly now: () => number
}

const EXIT_USAGE = BOOTSTRAP_EXIT.usage
const EXIT_OTHER = BOOTSTRAP_EXIT.other

class Usage extends Error {}
class Failure extends Error {
  constructor(
    message: string,
    readonly code: number,
  ) {
    super(message)
  }
}

interface Parsed {
  readonly values: Map<string, string>
  readonly flags: Set<string>
  readonly positional: string[]
}

function parseArgs(argv: readonly string[], valued: readonly string[], booleans: readonly string[], positional = false): Parsed {
  const values = new Map<string, string>()
  const flags = new Set<string>()
  const rest: string[] = []
  for (let i = 0; i < argv.length; i++) {
    const word = argv[i]!
    if (valued.includes(word)) {
      const value = argv[++i]
      if (value === undefined || value.startsWith("--")) throw new Usage(`${word} needs a value`)
      values.set(word, value)
    } else if (booleans.includes(word)) flags.add(word)
    else if (word.startsWith("-") || !positional) throw new Usage(`unknown argument ${word}`)
    else rest.push(word)
  }
  return { values, flags, positional: rest }
}

const required = (p: Parsed, flag: string): string => {
  const value = p.values.get(flag)
  if (value === undefined) throw new Usage(`${flag} is required`)
  return value
}

const describe = (issues: readonly Issue[]) => issues.map((i) => `  ${i.code} ${i.path || "/"}: ${i.message}`).join("\n")

/** Throws a Failure carrying the exit code of the first issue. */
function unwrap<T>(r: Result<T>, what: string): T {
  if (r.ok) return r.value
  throw new Failure(`${what}:\n${describe(r.issues)}`, exitFor(r.issues[0]?.code ?? "internal"))
}

function readJSON(file: string, what: string): unknown {
  let text: string
  try {
    text = readFileSync(file, "utf8")
  } catch {
    throw new Failure(`cannot read ${what} ${file}`, EXIT_OTHER)
  }
  const r = parseManifest(text)
  if (!r.ok) throw new Failure(`${what} ${file} is not JSON`, EXIT_OTHER)
  return r.value
}

function loadTrustRoot(file: string): TrustRoot {
  const value = readJSON(file, "trust root")
  const r = shippedTrustRoot(JSON.stringify(value))
  if (!r.ok) throw new Failure(`trust root ${file}:\n${describe(r.issues)}`, EXIT_OTHER)
  return r.value
}

function signingKey(io: ReleaseIo) {
  const secret = io.env[SIGNING_KEY_ENV]
  if (!secret) throw new Usage(`${SIGNING_KEY_ENV} is not set (the release signing key; a GitHub Actions secret)`)
  try {
    return parseSigningKey(secret)
  } catch (error) {
    throw new Failure((error as Error).message, EXIT_OTHER)
  }
}

/** The --targets list: supported targets, each named once; undefined when not given (every supported target). */
function targetsArg(p: Parsed): string[] | undefined {
  const text = p.values.get("--targets")
  if (text === undefined) return undefined
  const list = text.split(",").map((t) => t.trim())
  if (list.some((t) => t === "")) throw new Usage("--targets takes a comma-separated list of targets (e.g. linux-x64,darwin-arm64)")
  for (const target of list) {
    const r = checkTarget(target)
    if (!r.ok) throw new Usage(r.issues[0]!.message)
  }
  if (new Set(list).size !== list.length) throw new Usage("--targets names a target twice")
  return SUPPORTED_TARGETS.map((t) => t.target).filter((t) => list.includes(t))
}

/** The `bun build --compile` words for one target's hubctl. */
export function hubctlBuildArgv(target: string, options: { readonly bun: string; readonly outdir: string; readonly root?: TrustRoot }): string[] {
  const t = supportedTarget(target)
  if (!t) throw new Error(`${target} is not a supported target`)
  return [
    options.bun,
    "build",
    "--compile",
    "--minify",
    "--sourcemap",
    `--target=${t.bunTarget}`,
    ...(options.root ? trustRootDefine(options.root) : []),
    HUBCTL_ENTRY,
    "--outfile",
    path.join(options.outdir, hubctlFile(t.target)),
  ]
}

async function build(argv: readonly string[], io: ReleaseIo): Promise<number> {
  const p = parseArgs(argv, ["--outdir", "--trust-root", "--bun"], ["--require-trust-root"], true)
  const targets = p.positional.length > 0 ? p.positional : SUPPORTED_TARGETS.map((t) => t.target)
  for (const target of targets) {
    const r = checkTarget(target)
    if (!r.ok) throw new Usage(r.issues[0]!.message)
  }
  const rootFile = path.resolve(io.cwd, p.values.get("--trust-root") ?? TRUST_ROOT_FILE)
  let root: TrustRoot | undefined
  if (existsSync(rootFile)) root = loadTrustRoot(rootFile)
  else if (p.flags.has("--require-trust-root")) throw new Failure(`no trust root at ${rootFile}: a release build must embed one (see README.md next to ${TRUST_ROOT_FILE})`, EXIT_OTHER)
  else io.stderr(`warning: no trust root at ${rootFile}; this dev build cannot verify releases\n`)
  const outdir = path.resolve(io.cwd, p.values.get("--outdir") ?? "dist")
  mkdirSync(outdir, { recursive: true })
  const bun = p.values.get("--bun") ?? process.execPath
  for (const target of targets) {
    const words = hubctlBuildArgv(target, { bun, outdir, ...(root ? { root } : {}) })
    io.stderr(`==> ${words.at(-1)}\n`)
    const code = await io.run(words)
    if (code !== 0) throw new Failure(`bun build failed for ${target} (exit ${code})`, EXIT_OTHER)
  }
  return 0
}

/** Each target's built hubctl in `dist`, with its size and digest. */
function readArtifacts(dist: string, targets: readonly string[], what: string) {
  return targets.map((target) => {
    const file = hubctlFile(target)
    let bytes: Uint8Array
    try {
      bytes = readFileSync(path.join(dist, file))
    } catch {
      throw new Failure(`missing ${path.join(dist, file)}: build ${what} first`, EXIT_OTHER)
    }
    return { target, file, ...digestBytes(bytes) }
  })
}

async function manifest(argv: readonly string[], io: ReleaseIo): Promise<number> {
  const p = parseArgs(argv, ["--dist", "--pins", "--minimum-version", "--release", "--issued-at", "--out", "--targets"], [])
  const listed = targetsArg(p)
  const targets = listed ?? SUPPORTED_TARGETS.map((t) => t.target)
  const minimumVersion = required(p, "--minimum-version")
  const out = path.resolve(io.cwd, required(p, "--out"))
  const dist = path.resolve(io.cwd, p.values.get("--dist") ?? "dist")
  const issuedText = p.values.get("--issued-at")
  const issuedAt = issuedText === undefined ? io.now() : Number(issuedText)
  if (!Number.isSafeInteger(issuedAt) || issuedAt < 0) throw new Usage("--issued-at takes milliseconds since the epoch")
  const pins = unwrap(validatePinList(readJSON(path.resolve(io.cwd, p.values.get("--pins") ?? PIN_LIST_FILE), "pin list")), "the pin list is invalid")
  const artifacts = readArtifacts(dist, targets, listed ? "every listed target" : "every supported target (or name a subset with --targets)")
  io.stderr(`re-downloading ${pins.pins.length} pinned harness file(s)\n`)
  const harnesses = unwrap(await verifyPinDownloads(pins, io.download), "a pinned harness file does not match its pin")
  const body = unwrap(
    buildManifestBody({ release: p.values.get("--release") ?? HUBCTL_VERSION, minimumVersion, issuedAt, artifacts, harnesses, ...(listed ? { targets: listed } : {}) }),
    "the manifest is invalid",
  )
  writeFileSync(out, `${canonicalJSON(body)}\n`)
  io.stdout(`${out}: hubctl ${body.release} (${body.channel}), ${body.artifacts.length} artifacts (${body.artifacts.map((a) => a.target).join(", ")}), ${body.harnesses.length} harness pins\n`)
  return 0
}

async function sign(argv: readonly string[], io: ReleaseIo): Promise<number> {
  const p = parseArgs(argv, ["--in", "--out", "--trust-root", "--key-id", "--targets"], [])
  const listed = targetsArg(p)
  const input = path.resolve(io.cwd, required(p, "--in"))
  const out = path.resolve(io.cwd, required(p, "--out"))
  const root = loadTrustRoot(path.resolve(io.cwd, p.values.get("--trust-root") ?? TRUST_ROOT_FILE))
  const body = readJSON(input, "manifest body")
  if (!isRecord(body) || "signatures" in body) throw new Failure(`${input} is not an unsigned manifest body (it has signatures, or is not an object)`, EXIT_OTHER)
  const rebuilt = unwrap(
    buildManifestBody({
      release: body.release as string,
      minimumVersion: body.minimumVersion as string,
      issuedAt: body.issuedAt as number,
      artifacts: body.artifacts as never,
      harnesses: body.harnesses as never,
      ...(listed ? { targets: listed } : {}),
    }),
    "the manifest body is invalid (a partial release needs --targets naming its targets)",
  )
  if (canonicalJSON(rebuilt) !== canonicalJSON(body)) throw new Failure(`${input} is not a manifest body as \`manifest\` writes it`, EXIT_OTHER)
  const privateKey = signingKey(io)
  const active = root.keys.filter((k) => k.status === "active")
  const keyID = p.values.get("--key-id") ?? (active.length === 1 ? active[0]!.keyID : DEFAULT_KEY_ID)
  const verified = unwrap(signVerified(rebuilt, { keyID, privateKey }, root), "the signed manifest does not verify against the trust root (is the secret the key the binaries embed?)")
  writeFileSync(out, manifestJSON(verified))
  io.stdout(`${out}: signed by ${keyID}, verified against trust root v${root.version}\n`)
  return 0
}

async function verify(argv: readonly string[], io: ReleaseIo): Promise<number> {
  const p = parseArgs(argv, ["--manifest", "--trust-root", "--dist", "--target", "--file", "--installed", "--installed-sha256", "--floor", "--targets"], ["--allow-downgrade"])
  const listed = targetsArg(p)
  const root = loadTrustRoot(path.resolve(io.cwd, p.values.get("--trust-root") ?? TRUST_ROOT_FILE))
  const document = readJSON(path.resolve(io.cwd, required(p, "--manifest")), "manifest")
  const dist = p.values.get("--dist")
  if (listed && !dist) throw new Usage("--targets goes with --dist")
  const jobs: { target: string; file: string }[] = dist
    ? (listed ?? SUPPORTED_TARGETS.map((t) => t.target)).map((target) => ({ target, file: path.resolve(io.cwd, dist, hubctlFile(target)) }))
    : [{ target: required(p, "--target"), file: path.resolve(io.cwd, required(p, "--file")) }]
  const installedVersion = p.values.get("--installed")
  const installedSha = p.values.get("--installed-sha256")
  if ((installedVersion === undefined) !== (installedSha === undefined)) throw new Usage("--installed and --installed-sha256 go together")
  const floor = p.values.get("--floor")
  for (const job of jobs) {
    let bytes: Uint8Array
    try {
      bytes = readFileSync(job.file)
    } catch {
      throw new Failure(`cannot read ${job.file}`, EXIT_OTHER)
    }
    const accepted = unwrap(
      verifyHubctlRelease({
        manifest: document,
        root,
        target: job.target,
        bytes: digestBytes(bytes),
        ...(installedVersion !== undefined && installedSha !== undefined ? { installed: { version: installedVersion, sha256: installedSha } } : {}),
        ...(floor !== undefined ? { floor } : {}),
        allowDowngrade: p.flags.has("--allow-downgrade"),
      }),
      `${job.target}: rejected`,
    )
    io.stdout(`ok ${job.target} hubctl ${accepted.manifest.release} ${accepted.kind} ${accepted.artifact.sha256}\n`)
  }
  return 0
}

async function trustRoot(argv: readonly string[], io: ReleaseIo): Promise<number> {
  const p = parseArgs(argv, ["--key-id"], [])
  io.stdout(`${JSON.stringify(trustRootFor(signingKey(io), p.values.get("--key-id") ?? DEFAULT_KEY_ID), null, 2)}\n`)
  return 0
}

/** The file a dev release writes its (public) trust root to, in --out. */
export const DEV_TRUST_ROOT_FILE = "dev-trust-root.json"

async function dev(argv: readonly string[], io: ReleaseIo): Promise<number> {
  const p = parseArgs(argv, ["--targets", "--out", "--pins", "--pending", "--release", "--minimum-version", "--bun"], ["--skip-pin-download", "--no-pending"])
  // Never where a real release is made: a dev release is signed by a throwaway key and must never ship.
  if (io.env[SIGNING_KEY_ENV] !== undefined) throw new Usage(`refusing a dev release while ${SIGNING_KEY_ENV} is set (that is the release signing job); dev releases never ship`)
  if (io.env.GITHUB_ACTIONS === "true") throw new Usage("refusing a dev release on GitHub Actions; dev releases are for testing on your own machines and never ship")
  const listed = targetsArg(p)
  if (!listed) throw new Usage("--targets is required (e.g. --targets linux-x64,windows-x64)")
  const out = path.resolve(io.cwd, required(p, "--out"))
  const repoDist = path.resolve(io.cwd, "dist")
  if (out === repoDist || out.startsWith(`${repoDist}${path.sep}`)) throw new Usage(`refusing a dev release into ${repoDist}, where release builds go; choose another --out`)
  if (p.flags.has("--no-pending") && p.values.has("--pending")) throw new Usage("--pending and --no-pending exclude each other")

  // The pins: the reviewed list, plus the pending (unreviewed) one, which only a dev release ever includes.
  const reviewed = unwrap(validatePinList(readJSON(path.resolve(io.cwd, p.values.get("--pins") ?? PIN_LIST_FILE), "pin list")), "the pin list is invalid")
  const pending = p.flags.has("--no-pending")
    ? []
    : unwrap(validatePendingPinList(readJSON(path.resolve(io.cwd, p.values.get("--pending") ?? PENDING_PIN_LIST_FILE), "pending pin list")), "the pending pin list is invalid").pins
  const pins = [...reviewed.pins.map((e) => e.pin), ...pending.map((e) => e.pin)]
  const seen = new Set<string>()
  for (const pin of pins) {
    const key = `${pin.harness} ${pin.target}`
    if (seen.has(key)) throw new Failure(`${pin.harness} ${pin.target} is pinned in both the reviewed and the pending list; keep it in one`, EXIT_OTHER)
    seen.add(key)
  }
  for (const { pin } of pending) io.stderr(`including a PENDING (unreviewed) pin: ${pin.harness} ${pin.version} ${pin.target} (${pin.file}); dev release only\n`)
  if (!p.flags.has("--skip-pin-download")) {
    io.stderr(`re-downloading ${pins.length} pinned harness file(s)\n`)
    unwrap(await redownload(pins, io.download), "a pinned harness file does not match its pin")
  }

  // The throwaway key: in memory only. Its public trust root is written for reference (and for `verify`).
  const { privateKey } = generateKeyPairSync("ed25519")
  const keyID = `dev-${randomBytes(4).toString("hex")}`
  const root = trustRootFor(privateKey, keyID)
  mkdirSync(out, { recursive: true })
  writeFileSync(path.join(out, DEV_TRUST_ROOT_FILE), `${JSON.stringify(root, null, 2)}\n`)

  const bun = p.values.get("--bun") ?? process.execPath
  for (const target of listed) {
    const words = hubctlBuildArgv(target, { bun, outdir: out, root })
    io.stderr(`==> ${words.at(-1)}\n`)
    const code = await io.run(words)
    if (code !== 0) throw new Failure(`bun build failed for ${target} (exit ${code})`, EXIT_OTHER)
  }
  const artifacts = readArtifacts(out, listed, "every listed target")
  const body = unwrap(
    buildManifestBody({ release: p.values.get("--release") ?? HUBCTL_VERSION, minimumVersion: p.values.get("--minimum-version") ?? "0.0.0", issuedAt: io.now(), artifacts, harnesses: sortPins(pins), targets: listed }),
    "the manifest is invalid",
  )
  const verified = unwrap(signVerified(body, { keyID, privateKey }, root), "the dev manifest does not verify against its own trust root")
  writeFileSync(path.join(out, "hubctl-manifest.json"), manifestJSON(verified))
  // As sha256sum prints it (install.sh and install.ps1 read this file).
  writeFileSync(path.join(out, "HUBCTL_SHA256SUMS"), artifacts.map((a) => `${a.sha256.slice("sha256:".length)}  ${a.file}\n`).join(""))
  io.stdout(
    `${out}: DEV release hubctl ${body.release} (${artifacts.map((a) => a.file).join(", ")}), ${body.harnesses.length} harness pins (${pending.length} pending), signed by throwaway key ${keyID}\n` +
      `serve it:   cd ${out} && python3 -m http.server 8000 --bind 0.0.0.0\n` +
      `on the hub: HUB_RELEASE_BASE=http://<this machine's LAN IP>:8000\n`,
  )
  return 0
}

const COMMANDS: Record<string, (argv: readonly string[], io: ReleaseIo) => Promise<number>> = { build, manifest, sign, verify, "trust-root": trustRoot, dev }

const USAGE = "usage: hubctl-release <build|manifest|sign|verify|trust-root|dev> [options] (see packages/cli/src/bootstrap/release/cli.ts)\n"

export async function runRelease(argv: readonly string[], io: ReleaseIo): Promise<number> {
  const [name, ...rest] = argv
  const command = name !== undefined && Object.hasOwn(COMMANDS, name) ? COMMANDS[name] : undefined
  if (!command) {
    io.stderr(USAGE)
    return EXIT_USAGE
  }
  try {
    return await command(rest, io)
  } catch (error) {
    if (error instanceof Usage) {
      io.stderr(`${error.message}\n${USAGE}`)
      return EXIT_USAGE
    }
    if (error instanceof Failure) {
      io.stderr(`${error.message}\n`)
      return error.code
    }
    io.stderr(`internal error: ${error instanceof Error ? error.message : String(error)}\n`)
    return EXIT_OTHER
  }
}

// The Claude Code bootstrap adapter (HBS-08): planning and discovery (adapter.ts), the pinned-artifact source with
// optional upstream evidence (source.ts, openpgp.ts), real readiness probes (verify.ts), and the injected ports
// (ports.ts) with their default Node implementations (node.ts). Integration into the CLI is HBS-13's.
import type { HarnessVerification } from "../../contracts/index.ts"
import { installHarnessExecutor, type HarnessSource } from "../../transaction/builtin.ts"
import type { ActionExecutor } from "../../transaction/executor.ts"
import type { ReadinessGate } from "../readiness.ts"
import { claudeVerifyExecutor } from "./verify.ts"

export * from "./adapter.ts"
export * from "./node.ts"
export * from "./openpgp.ts"
export * from "./ports.ts"
export * from "./source.ts"
export * from "./verify.ts"

export interface ClaudeExecutorOptions extends ReadinessGate {
  /** createClaudeHarnessSource(...) */
  readonly source: HarnessSource
  /** adapter.verify(context) */
  readonly verify: () => Promise<HarnessVerification>
  readonly now: () => number
  readonly onVerified?: (verification: HarnessVerification) => void
}

/**
 * The executors the Claude Code plan needs beyond the built-in local ones: install-harness from the Claude Code
 * source, and verify-harness for claude-code. The engine has one executor per kind, so with several harnesses the
 * integrator dispatches these by `action.harness` (HBS-13).
 */
export function claudeExecutors(options: ClaudeExecutorOptions): { readonly "install-harness": ActionExecutor<"install-harness">; readonly "verify-harness": ActionExecutor<"verify-harness"> } {
  return {
    "install-harness": installHarnessExecutor(options.source),
    "verify-harness": claudeVerifyExecutor({
      verify: options.verify,
      now: options.now,
      ...(options.onVerified ? { onVerified: options.onVerified } : {}),
      ...(options.requireReady !== undefined ? { requireReady: options.requireReady } : {}),
      ...(options.onReadiness ? { onReadiness: options.onReadiness } : {}),
    }),
  }
}

// The Codex bootstrap adapter (HBS-09). Codex is the third harness in HARNESS_ORDER.
//
//   createCodexAdapter       the HarnessAdapter: discover (presence only), plan (planCodex: pinned install-harness,
//                            select-harness-version, verify-harness with real probes; no ~/.codex edit unless the
//                            opt-in TOML edit, which becomes a manual edit), verify (verifyCodex)
//   createCodexHarnessSource the HarnessSource for the built-in install-harness executor (pinned download,
//                            sigstore evidence, unpack)
//   codexVerifyExecutor      the verify-harness executor (harness_not_ready unless advertised ready)
//   codexCapabilities        the explicit, probe-backed capability advertisement
//
// Hub wiring reuses packages/codex: the app-server handshake (openAppServer) and stdio channel the Codex spoke uses
// probe the app-server, and the spoke itself (hub codex-spoke serve) is what spoke-connected checks for.
import type { DiscoverySnapshot, HarnessAdapter, HarnessPresence, VerifiedManifest } from "../../contracts/index.ts"
import { codexPinFor, planCodex } from "./plan.ts"
import { codexBinaryPath, verifyCodex, type CodexProbes } from "./verify.ts"

export * from "./archive.ts"
export * from "./sigstore.ts"
export * from "./source.ts"
export * from "./plan.ts"
export * from "./verify.ts"

export interface CodexAdapterOptions {
  /** The verified hub release manifest (its codex pins). */
  readonly manifest: VerifiedManifest
  /** The injected probe capabilities; the binary and expected version come from the snapshot and the pin. */
  readonly probes: Omit<CodexProbes, "binary" | "expectedVersion"> & Partial<Pick<CodexProbes, "binary">>
  /** The discovery snapshot of this host (discover reads presence from it). */
  readonly snapshot: () => DiscoverySnapshot | undefined
  /** The hub-installed Codex recorded before (profile history), for rollback records. */
  readonly previous?: { readonly version: string; readonly sha256: string }
  /** Opt-in: ask for features.daemon_auto_start in ~/.codex/config.toml (a TOML manual edit). */
  readonly ensureDaemonFeature?: boolean
}

export interface CodexAdapter extends HarnessAdapter {
  readonly options: CodexAdapterOptions
}

const NOT_FOUND: HarnessPresence = { id: "codex", installed: false, health: { state: "unverified", probes: [] } }

export function createCodexAdapter(options: CodexAdapterOptions): CodexAdapter {
  const pinFor = (snapshot: DiscoverySnapshot | undefined) => (snapshot ? codexPinFor(options.manifest, snapshot.host.target) : undefined)
  return {
    id: "codex",
    options,
    async discover() {
      const found = options.snapshot()?.harnesses.find((h) => h.id === "codex")
      // Presence only: health stays unverified until verify runs the real probes.
      return found ? { ...found, health: { state: "unverified", probes: [] } } : NOT_FOUND
    },
    plan: (input) => planCodex(input, { manifest: options.manifest, ...(options.previous ? { previous: options.previous } : {}), ...(options.ensureDaemonFeature ? { ensureDaemonFeature: true } : {}) }),
    async verify(context) {
      const snapshot = options.snapshot()
      const pin = pinFor(snapshot)
      const binary = options.probes.binary ?? (() => (snapshot ? codexBinaryPath(snapshot, { preferHub: pin !== undefined }) : undefined))
      return verifyCodex(context, { ...options.probes, binary, ...(pin ? { expectedVersion: pin.version } : {}) })
    },
  }
}

// The node-services adapter: a persistent launch node (`hub node`) and the harness spokes' user services, planned
// from the embedded unit templates, loaded only with explicit consent through fixed-argv calls to the user's
// service manager, and proved by one bounded verification launch.
//
//   render.ts    the units, from EMBEDDED_ASSETS with serviceArgv (golden-tested for systemd --user and launchd)
//   validate.ts  narrow node settings (roots, slots, labels) and the same-runtime-context rule
//   plan.ts      the typed actions (node.json merge, install-service, activate-service, launch-session)
//   control.ts   ServiceControl over systemctl --user / launchctl, and the activate-service executor
//   launch.ts    the bounded launch verification and the launch-session executor
import type { ExecutorMap } from "../../transaction/executor.ts"
import { activateServiceExecutor, type NodeServiceControl } from "./control.ts"
import { launchSessionExecutor, type LaunchProbe } from "./launch.ts"

export * from "./render.ts"
export * from "./validate.ts"
export * from "./plan.ts"
export * from "./control.ts"
export * from "./launch.ts"

/** The executors this adapter adds to builtinExecutors (pass the same control as BuiltinDeps.services). */
export function nodeServiceExecutors(deps: { readonly control?: NodeServiceControl; readonly probe?: LaunchProbe }): Pick<ExecutorMap, "activate-service" | "launch-session"> {
  return { "activate-service": activateServiceExecutor(deps.control), "launch-session": launchSessionExecutor(deps.probe) }
}

// The OpenCode harness adapter (HBS-06): one entry point for the integrator (HBS-13), built on the frozen bootstrap
// contracts. createOpencodeHarness wires the pure planner (plan.ts), discovery-backed presence, the real readiness
// probes (verify.ts), the pinned-artifact source (apply.ts, archive.ts) and the executors for register-mcp-server
// and verify-harness. Every capability is injected: a read-only DiscoveryProbe, a fixed-argv ProcessRunner, the hub
// spoke probe, the download. See README.md for the upstream source findings and the integration requirements.
import { executionContextOf, resolvePathRef, type AdapterContext, type HarnessAdapter, type HarnessPresence, type HarnessVerification, type PathRef, type VerifiedManifest } from "../../contracts/index.ts"
import { discover } from "../../discovery/discover.ts"
import type { DiscoveryProbe } from "../../discovery/probe.ts"
import type { HarnessSource } from "../../transaction/builtin.ts"
import type { ExecutorMap } from "../../transaction/executor.ts"
import type { ReadinessGate } from "../readiness.ts"
import { createOpencodeHarnessSource, httpsDownload, opencodeExecutors, type Download } from "./apply.ts"
import { hubMcpCommand, inspectOpencodeConfig, samePath } from "./config.ts"
import { authorityFor, CONFIG_REFS, createOpencodeAdapter, DEFAULT_AUTHORITY, mcpCommandPath, type OpencodePlanOptions } from "./plan.ts"
import { hubManagedVersion, locateOpencodeBinary, nodeProcessRunner, verifyOpencode, type ProcessRunner, type ProviderProbe, type SpokeProbe } from "./verify.ts"

export * from "./archive.ts"
export * from "./config.ts"
export * from "./plan.ts"
export * from "./verify.ts"
export * from "./apply.ts"

export interface OpencodeHarnessOptions extends Omit<OpencodePlanOptions, "readConfig"> {
  /** Read-only host access (createNodeProbe() in the CLI, memoryProbe() in tests). */
  readonly probe: DiscoveryProbe
  /** Default: nodeProcessRunner (execFile, no shell). */
  readonly runner?: ProcessRunner
  /** Whether the hub sees this machine's OpenCode spoke; without it OpenCode is never ready. */
  readonly spoke?: SpokeProbe
  readonly provider?: ProviderProbe
  /** Default: httpsDownload(fetch). */
  readonly download?: Download
  /** Downgrade-policy inputs for the harness source (from the install history). */
  readonly installed?: () => { readonly version: string; readonly sha256: string } | undefined
  readonly floor?: () => string | undefined
  readonly allowDowngrade?: boolean
  readonly onVerification?: (verification: HarnessVerification) => void
}

export interface OpencodeHarness {
  readonly adapter: HarnessAdapter
  /** Absent without a manifest (nothing can be installed then). */
  readonly source?: HarnessSource
  /** Executors for apply's context: merge them over builtinExecutors. `gate`: the v1.2 readiness gate. */
  executors(context: () => AdapterContext, gate?: ReadinessGate): Pick<ExecutorMap, "register-mcp-server" | "verify-harness">
}

export function createOpencodeHarness(options: OpencodeHarnessOptions): OpencodeHarness {
  const { probe } = options
  const runner = options.runner ?? nodeProcessRunner
  const presence = async (context: AdapterContext): Promise<HarnessPresence> => {
    const snap = discover(probe, { now: context.now() })
    const found = snap.ok ? snap.value.harnesses.find((h) => h.id === "opencode") : undefined
    return found ?? { id: "opencode", installed: false, health: { state: "unverified", probes: [] } }
  }
  const verify = async (context: AdapterContext): Promise<HarnessVerification> => {
    // Located fresh at every verification: after an install, `current` points at the new version.
    const located = locateOpencodeBinary(probe)
    const binary = located.ok ? located.value : undefined
    const expectVersion = binary ? hubManagedVersion(binary) : undefined
    // (PM-2) What OpenCode's config registers now: the plugin's pin and the hub MCP server's command.
    const registered = registrations(probe, context, (options.authority as PathRef | undefined) ?? DEFAULT_AUTHORITY)
    return verifyOpencode(context, {
      runner,
      binary,
      ...(options.spoke ? { spoke: options.spoke } : {}),
      ...(options.provider ? { provider: options.provider } : {}),
      ...(expectVersion ? { expectVersion } : {}),
      ...(registered.mcp !== undefined ? { mcp: registered.mcp } : {}),
      ...(registered.pinned ? { expectPluginVersion: registered.pinned } : options.pluginVersion ? { minPluginVersion: options.pluginVersion } : {}),
    })
  }
  const adapter = createOpencodeAdapter({ ...options, readConfig: (path) => probe.readFile(path), discover: presence, verify })
  const source = options.manifest
    ? createOpencodeHarnessSource({
        manifest: options.manifest as VerifiedManifest,
        download: options.download ?? httpsDownload(),
        ...(options.installed ? { installed: options.installed } : {}),
        ...(options.floor ? { floor: options.floor } : {}),
        ...(options.allowDowngrade ? { allowDowngrade: true } : {}),
      })
    : undefined
  return {
    adapter,
    ...(source ? { source } : {}),
    executors: (context, gate = {}) =>
      opencodeExecutors({ adapter, context, ...gate, ...(options.authority ? { authority: options.authority as PathRef } : {}), ...(options.onVerification ? { onVerification: options.onVerification } : {}) }),
  }
}

/**
 * (PM-2) The first OpenCode config hubctl edits, as it is now: the npm plugin's pin (undefined: unpinned or none) and
 * the hub MCP server's command (false: none registered; undefined: the host or the config cannot be read).
 */
function registrations(probe: DiscoveryProbe, context: AdapterContext, authority: PathRef): { readonly pinned?: string; readonly mcp?: string | false | "foreign" } {
  const snap = discover(probe, { now: context.now() })
  if (!snap.ok) return {}
  // The stable hubctl authority setup registers (the same path register-mcp-server writes): only it is ever run.
  const ref = authorityFor(authority, snap.value.host.target)
  const resolved = ref.ok ? resolvePathRef(ref.value, snap.value.roots, executionContextOf(snap.value)) : undefined
  const stable = resolved?.ok ? mcpCommandPath(resolved.value, snap.value.host.target) : undefined
  for (const { ref } of CONFIG_REFS) {
    const where = resolvePathRef(ref, snap.value.roots, executionContextOf(snap.value))
    const bytes = where.ok ? probe.readFile(where.value) : undefined
    if (!bytes) continue
    const text = new TextDecoder().decode(bytes)
    const seen = inspectOpencodeConfig(text, { authority: "" })
    const plugin = seen.ok ? seen.value.plugin : undefined
    const pinned = plugin && plugin.state !== "absent" && plugin.source === "npm" ? plugin.found : undefined
    // The hub MCP server, read on its own (a foreign command there makes the inspection refuse): only the hub CLI
    // is ever run. OpenCode's config holds a native path on Windows (C:\\…): the runner takes the canonical C:/… form.
    const server = hubMcpCommand(text)
    // Not the recorded authority path (another hubctl, GitHub's `hub`, or no recorded path): "foreign", not run.
    const ours = server && server.hub && stable !== undefined && samePath(server.command, stable)
    const mcp = !server ? false : !ours ? ("foreign" as const) : /^[A-Za-z]:\\/.test(server!.command) ? server!.command.replace(/\\/g, "/") : server!.command
    return { ...(pinned ? { pinned } : {}), mcp }
  }
  return { mcp: false }
}
